20	/*!
21	 * \file flatten_buffer.cc
22	 */
23	
24	#include "arith/ir_mutator_with_analyzer.h"
25	#include "tir/transforms/ir_utils.h"
26	#include <tvm/arith/iter_affine_map.h>
27	#include <tvm/ffi/reflection/registry.h>
28	#include <tvm/ir/attrs.h>
29	#include <tvm/tir/analysis.h>
30	#include <tvm/tir/data_type_rewriter.h>
31	#include <tvm/tir/stmt_functor.h>
32	#include <tvm/tir/transform.h>
33	
34	#include <utility>
35	
36	#include "../op/builtin.h"
37	
38	namespace tvm {
39	namespace tl {
40	
41	using namespace tir;
42	
43	/*!
44	 * \brief Transform multi-dimension BufferLoad/BufferStore into device-supported
45	 * dimension for the TIR not contains opaque block.
46	 */
47	class BufferFlattener : public arith::IRMutatorWithAnalyzer {
48	public:
49	  static PrimFunc Flatten(PrimFunc func) {
50	    arith::Analyzer ana;
51	    auto pass = BufferFlattener(&ana);
52	    if (auto init_map =
53	            func->attrs.GetAttr<Map<Var, PrimExpr>>(tl::attr::kLocalVarInit)) {
54	      pass.local_var_init_map_ = init_map.value();
55	    }
56	    auto writer = func.CopyOnWrite();
57	    pass.MarkBufferMapShapes(func);
58	    writer->body = pass.VisitStmt(func->body);
59	    // The buffers in func->buffer_map are deliberately left
60	    // unflattened, as they are used for validation of user-provided
61	    // arguments.  The flattened buffers used in the updated
62	    // function body alias the argument buffers.
63	    return func;
64	  }
65	
66	private:
67	  using IRMutatorWithAnalyzer::VisitExpr;
68	  using IRMutatorWithAnalyzer::VisitExpr_;
69	  using IRMutatorWithAnalyzer::VisitStmt;
70	  using IRMutatorWithAnalyzer::VisitStmt_;
71	
72	  class Int64Promoter : public tir::IndexDataTypeRewriter {
73	  public:
74	    using Parent = IndexDataTypeRewriter;
75	
76	    PrimExpr VisitExpr_(const VarNode *op) final {
77	      if (op->dtype.is_int() && op->dtype.bits() < 64) {
78	        return cast(DataType::Int(64), tvm::ffi::GetRef<Var>(op));
79	      }
80	      return tvm::ffi::GetRef<PrimExpr>(op);
81	    }
82	
83	    PrimExpr VisitExpr_(const IntImmNode *op) final {
84	      if (op->dtype.is_int() && op->dtype.bits() < 64) {
85	        return IntImm(DataType::Int(64), op->value);
86	      }
87	      return tvm::ffi::GetRef<PrimExpr>(op);
88	    }
89	
90	    PrimExpr VisitExpr_(const CastNode *op) final {
91	      if (op->dtype.is_int() && op->dtype.bits() < 64) {
92	        return cast(DataType::Int(64), op->value);
93	      }
94	      return tvm::ffi::GetRef<PrimExpr>(op);
95	    }
96	
97	    Stmt VisitStmt_(const BufferStoreNode *op) final {
98	      // Force indices to be int64
99	      auto node = Downcast<BufferStore>(Parent::VisitStmt_(op));
100	      return std::move(node);
101	    }
102	
103	    PrimExpr VisitExpr_(const BufferLoadNode *op) final {
104	      auto node = Downcast<BufferLoad>(Parent::VisitExpr_(op));
105	      return std::move(node);
106	    }
107	  };
108	
109	  explicit BufferFlattener(arith::Analyzer *ana) : IRMutatorWithAnalyzer(ana) {}
110	
111	  Stmt VisitStmt_(const BlockNode *op) final {
112	    ICHECK_EQ(op->match_buffers.size(), 0)
113	        << "Unexpected MatchBufferRegion found during "
114	           "tir.transform.FlattenBuffer.  "
115	        << "All MatchBufferRegion should be removed in "
116	           "tir.transform.LowerMatchBuffer.";
117	
118	    Block block = tvm::ffi::GetRef<Block>(op);
119	
120	    Array<Buffer> alloc_buffers = op->alloc_buffers;
121	    alloc_buffers.MutateByApply(
122	        [this](const Buffer &buf) { return GetFlattenedBuffer(buf); });
123	    if (!alloc_buffers.same_as(op->alloc_buffers)) {
124	      block.CopyOnWrite()->alloc_buffers = alloc_buffers;
125	    }
126	
127	    Array<BufferRegion> reads = op->reads;
128	    reads.MutateByApply([this](BufferRegion region) {
129	      return MutateBufferRegion(std::move(region));
130	    });
131	    if (!reads.same_as(op->reads)) {
132	      block.CopyOnWrite()->reads = reads;
133	    }
134	
135	    Array<BufferRegion> writes = op->writes;
136	    writes.MutateByApply([this](BufferRegion region) {
137	      return MutateBufferRegion(std::move(region));
138	    });
139	    if (!writes.same_as(op->writes)) {
140	      block.CopyOnWrite()->writes = writes;
141	    }
142	
143	    return StmtExprMutator::VisitStmt_(block.get());
144	  }
145	
146	  Stmt VisitStmt_(const AllocateNode *op) final {
147	    // Determine the flattened extents first, before stripping of
148	    // DeclBuffer.
149	    auto new_extents = [&]() -> Array<PrimExpr> {
150	      if (op->extents.size() == 1) {
151	        // No flattening required for buffers that are already flat
152	        return op->extents;
153	      }
154	
155	      if (auto *decl_buffer = op->body.as<DeclBufferNode>()) {
156	        // N-d buffer, use the DeclBuffer inside to determine how it
157	        // should be flattened.
158	        auto &buffer = decl_buffer->buffer;
159	        bool matching_buffer = [&]() {
160	          if (!decl_buffer->buffer->data.same_as(op->buffer_var)) {
161	            return false;
162	          }
163	          if (op->dtype != buffer->dtype) {
164	            return false;
165	          }
166	          if (op->extents.size() != buffer->shape.size()) {
167	            return false;
168	          }
169	          ExprDeepEqual expr_equal;
170	          for (size_t i = 0; i < op->extents.size(); i++) {
171	            if (!expr_equal(op->extents[i], buffer->shape[i])) {
172	              return false;
173	            }
174	          }
175	          return true;
176	        }();
177	
178	        if (matching_buffer) {
179	          Buffer flattened = GetFlattenedBuffer(buffer);
180	          return flattened->shape;
181	        } else {
182	          ICHECK(decl_buffer->buffer->axis_separators.empty())
183	              << "DeclBuffer node doesn't match Allocate extents, but also "
184	                 "shouldn't be "
185	                 "flattened to 1-d physical memory";
186	        }
187	      }
188	
189	      // Fallback, this is an allocation without a matching DeclBuffer
190	      PrimExpr flat_extent = 1;
191	      for (const auto &dim : op->extents) {
192	        flat_extent *= dim;
193	      }
194	      return {flat_extent};
195	    }();
196	
197	    Allocate alloc = Downcast<Allocate>(StmtExprMutator::VisitStmt_(op));
198	
199	    // TODO(Lunderberg): Move the handling of boolean into a
200	    // dedicated pass.
201	    if (alloc->dtype == DataType::Bool()) {
202	      alloc.CopyOnWrite()->dtype = DataType::Int(8);
203	    }
204	
205	    if (!new_extents.same_as(alloc->extents)) {
206	      alloc.CopyOnWrite()->extents = new_extents;
207	    }
208	    if (!local_var_init_map_.empty()) {
209	      auto init_it = local_var_init_map_.find(alloc->buffer_var);
210	      if (init_it != local_var_init_map_.end()) {
211	        const PrimExpr &init = (*init_it).second;
212	        alloc.CopyOnWrite()->annotations.Set(tl::attr::kLocalVarInit, init);
213	      }
214	    }
215	
216	    return std::move(alloc);
217	  }
218	
219	  Stmt VisitStmt_(const DeclBufferNode *op) final {
220	    // TODO(rfc-70): Update the DeclBuffer node instead of
221	    // stripping it out.  Stripping it out in the current
222	    // implementation as not all lowering passes support
223	    // DeclBuffer.
224	    return VisitStmt(op->body);
225	  }
226	
227	  Buffer GetFlattenedBuffer(const Buffer &buf) {
228	    auto it = buffer_remap_.find(buf);
229	    if (it != buffer_remap_.end()) {
230	      return it->second;
231	    }
232	    auto flattened = buf.GetFlattenedBuffer();
233	    auto writer = flattened.CopyOnWrite();
234	
235	    // TODO(Lunderberg): Move the handling of boolean into a
236	    // dedicated pass.
237	    if (flattened->dtype == DataType::Bool()) {
238	      writer->dtype = DataType::Int(8);
239	    }
240	    // canonicalize shape
241	    for (size_t i = 0; i < flattened->shape.size(); ++i) {
242	      writer->shape.Set(i, analyzer_->canonical_simplify(flattened->shape[i]));
243	    }
244	
245	    buffer_remap_[buf] = flattened;
246	    return flattened;
247	  }
248	
249	  Stmt VisitStmt_(const BufferStoreNode *op) final {
250	    BufferStore store = Downcast<BufferStore>(StmtExprMutator::VisitStmt_(op));
251	    bool store_returns_bool = (op->value.dtype() == DataType::Bool());
252	    store = VisitBufferAccess(store);
253	
254	    // Handle casts from the value's dtype to the dtype of the
255	    // backing array.
256	    // TODO(Lunderberg): Move the handling of boolean into a
257	    // dedicated pass.
258	    if (store_returns_bool) {
259	      ICHECK_EQ(store->buffer->dtype, DataType::Int(8))
260	          << "Expected int8 backing array for boolean tensor";
261	      auto writer = store.CopyOnWrite();
262	      writer->value = tvm::cast(DataType::Int(8), store->value);
263	      return std::move(store);
264	    }
265	    return std::move(store);
266	  }
267	
268	  PrimExpr VisitExpr_(const BufferLoadNode *op) final {
269	    bool load_returns_bool = (op->dtype == DataType::Bool());
270	    BufferLoad load = Downcast<BufferLoad>(StmtExprMutator::VisitExpr_(op));
271	    load = VisitBufferAccess(load);
272	    // Handle casts from dtype of the backing array to value's dtype.
273	    // TODO(Lunderberg): Move the handling of boolean into a
274	    // dedicated pass.
275	    if (load_returns_bool && !under_address_of) {
276	      ICHECK_EQ(load->buffer->dtype, DataType::Int(8))
277	          << "Expected int8 backing array for boolean tensor";
278	      load.CopyOnWrite()->dtype = DataType::Int(8);
279	      return tvm::cast(DataType::Bool(), load);
280	    } else {
281	      return std::move(load);
282	    }
283	  }
284	
285	  PrimExpr VisitExpr_(const CallNode *op) final {
286	    if (op->op.same_as(builtin::address_of())) {
287	      under_address_of = true;
288	      auto result = StmtExprMutator::VisitExpr_(op);
289	      under_address_of = false;
290	      return result;
291	    }
292	    return StmtExprMutator::VisitExpr_(op);
293	  }
294	
295	  Array<PrimExpr> GetSimplifiedElemOffset(const Buffer &buffer,
296	                                          const Array<PrimExpr> &indices) {
297	    auto flattened_indices = buffer->ElemOffset(indices);
298	    Array<PrimExpr> safe_indices;
299	    for (auto index : flattened_indices) {
300	      auto int_bound = analyzer_->const_int_bound(index);
301	      DataType dtype = index->dtype;
302	      if (dtype.is_int() && dtype.bits() < 64) {
303	        int64_t max_value = int_bound->max_value;
304	        int64_t min_value = int_bound->min_value;
305	        const int64_t type_max = (1LL << (dtype.bits() - 1));
306	        const int64_t type_min = -(1LL << (dtype.bits() - 1));
307	
308	        if (max_value >= (type_max - 1) || min_value < type_min) {
309	          Int64Promoter promoter;
310	          for (auto &index : flattened_indices) {
311	            safe_indices.push_back(promoter(index));
312	          }
313	        } else {
314	          safe_indices.push_back(index);
315	        }
316	      } else {
317	        safe_indices.push_back(index);
318	      }
319	    }
320	    return this->IterMapSimplifyWithContext(safe_indices, false);
321	  }
322	
323	  template <typename Node> Node VisitBufferAccess(Node node) {
324	    ICHECK(node->buffer.defined());
325	    auto flattened_indices =
326	        GetSimplifiedElemOffset(node->buffer, node->indices);
327	    Buffer flattened_buffer = GetFlattenedBuffer(node->buffer);
328	
329	    auto writer = node.CopyOnWrite();
330	    writer->buffer = flattened_buffer;
331	    writer->indices = flattened_indices;
332	    return node;
333	  }
334	
335	  BufferRegion MutateBufferRegion(BufferRegion region) {
336	    Buffer orig_buf = region->buffer;
337	    Buffer flattened_buf = GetFlattenedBuffer(orig_buf);
338	    if (flattened_buf.same_as(orig_buf)) {
339	      return region;
340	    }
341	
342	    Array<PrimExpr> min_values;
343	    Array<PrimExpr> max_values;
344	    for (const auto &range : region->region) {
345	      min_values.push_back(range->min);
346	      max_values.push_back(range->min + range->extent - 1);
347	    }
348	
349	    Array<PrimExpr> flattened_min =
350	        GetSimplifiedElemOffset(orig_buf, min_values);
351	    Array<PrimExpr> flattened_max =
352	        GetSimplifiedElemOffset(orig_buf, max_values);
353	
354	    Array<Range> flattened_ranges;
355	    ICHECK_EQ(flattened_min.size(), flattened_max.size());
356	    for (size_t i = 0; i < flattened_min.size(); i++) {
357	      flattened_ranges.push_back(Range(flattened_min[i], flattened_max[i] + 1));
358	    }
359	
360	    return BufferRegion(flattened_buf, flattened_ranges);
361	  }
362	
363	  /*! \brief Whether the current buffer is under address_of */
364	  bool under_address_of = false;
365	  /*! \brief Map of buffers being remapped. */
366	  std::unordered_map<Buffer, Buffer, ObjectPtrHash, ObjectPtrEqual>
367	      buffer_remap_;
368	
369	  /*! \brief The updated external buffer map. */
370	  Map<Var, Buffer> updated_extern_buffer_map_;
371	
372	  /*! \brief Local var initializers preserved from block annotations. */
373	  Map<Var, PrimExpr> local_var_init_map_;
374	};
375	
376	PrimFunc FlattenBufferRewriter(PrimFunc f) {
377	  return BufferFlattener::Flatten(std::move(f));
378	}
379	
380	using namespace tir::transform;
381	tvm::transform::Pass FlattenBuffer() {
382	  auto pass_func = [=](PrimFunc f, const IRModule &m, const PassContext &ctx) {
383	    return FlattenBufferRewriter(std::move(f));
384	  };
385	  return CreatePrimFuncPass(pass_func, 0, "tl.FlattenBuffer", {});
386	}
387	
388	TVM_FFI_STATIC_INIT_BLOCK() {
389	  namespace refl = tvm::ffi::reflection;
390	  refl::GlobalDef().def("tl.transform.FlattenBuffer", FlattenBuffer);
391	}
392	
393	} // namespace tl
394	} // namespace tvm
