57	
58	static bool IsDynamicSharedMemory(Var buffer_var) {
59	  StorageScope storage_scope =
60	      runtime::StorageScope::Create(GetPtrStorageScope(std::move(buffer_var)));
61	  return storage_scope.rank == runtime::StorageRank::kShared &&
62	         storage_scope.tag == ".dyn";
63	}
64	
65	static bool IsStaticSharedMemory(Var buffer_var) {
66	  StorageScope storage_scope =
67	      runtime::StorageScope::Create(GetPtrStorageScope(std::move(buffer_var)));
68	  return storage_scope.rank == runtime::StorageRank::kShared &&
69	         storage_scope.tag.empty();
70	}
71	
72	/*!
73	 * \brief collect the mapping from the buffer var to its allocate
74	 */
75	class AllocateCollector : public StmtExprVisitor {
76	public:
77	  void VisitStmt_(const AllocateNode *op) final {
78	    if (IsDynamicSharedMemory(op->buffer_var)) {
79	      dyn_shmem_allocs_[op->buffer_var.get()] = op;
80	    } else if (IsStaticSharedMemory(op->buffer_var)) {
81	      static_shmem_allocs_[op->buffer_var.get()] = op;
82	    }
83	    StmtExprVisitor::VisitStmt_(op);
84	  }
85	  // The dynamic mapping from the original buffer var to its allocate
86	  std::unordered_map<const VarNode *, const AllocateNode *> dyn_shmem_allocs_;
87	  // The static mapping from the original buffer var to its allocate
88	  std::unordered_map<const VarNode *, const AllocateNode *>
89	      static_shmem_allocs_;
90	};
91	
92	// Find a linear pattern of storage access
93	// Used for liveness analysis.
94	// "linear" means fitting a complex access pattern into an array of StmtEntry
95	//
96	// Define "scope" as the body of For/thread_launch/IfThenElse
97	// Composite scopes(loop/thread_launch/IfThen) is represented by three
98	// StmtEntry: before_scope -> scope_body -> after_scope
99	//
100	// This pass tries to detect last point that we need to keep memory
101	// alive under the same scope as Allocate.
102	// The storage need to be kept alive between Allocate and last access.
103	// The free point is only inserted at the same scope of Allocate.
104	//
105	class SharedMemLinearAccessPatternFinder final : public StmtExprVisitor {
106	public:
107	  explicit SharedMemLinearAccessPatternFinder(
108	      bool is_dynamic = true, bool enable_aggressive_merge = false,
109	      bool verbose = false)
110	      : is_dynamic_(is_dynamic),
111	        enable_aggressive_merge_(enable_aggressive_merge), verbose_(verbose) {}
112	  /*! \brief record the touch list of statement. */
113	  struct StmtEntry {
114	    // The statement
115	    const Object *stmt{};
116	    // The index in the linear_seq_ to point to end of the nested scope.
117	    // This is only set to non-zero if stmt is a nested scope.
118	    // if offset > 0, means this is the begin, the end entry is current_index +
119	    // offset if offset < 0, means this is the end, the begin entry is
120	    // current_index + offset
121	    int64_t scope_pair_offset{0};
122	    // The buffer variables this statement touched.
123	    std::vector<const VarNode *> touched;
124	  };
125	  // The scope of each allocation
126	  struct AllocEntry {
127	    // the level in the scope stack
128	    size_t level{0};
129	    // allocation stmt
130	    const AllocateNode *alloc{nullptr};
131	  };
132	
133	  struct StmtAttr {
134	    // the level in the scope stack
135	    size_t level{0};
136	  };
137	
138	  void UpdateStmtAttr(const Object *stmt, size_t level) {
139	    if (stmt_attrs_.find(stmt) == stmt_attrs_.end()) {
140	      stmt_attrs_[stmt] = StmtAttr{level};
141	    } else {
142	      stmt_attrs_[stmt].level = level;
143	    }
144	  }
145	
146	  void VisitStmt_(const AllocateNode *op) final {
147	    size_t level = scope_.size();
148	    const VarNode *buf = op->buffer_var.get();
149	    // Record the allocation site and depth so liveness can reason about the
150	    // original scope.
151	    alloc_info_[buf].alloc = op;
152	    alloc_info_[buf].level = level;
153	    StmtExprVisitor::VisitStmt_(op);
154	  }
155	
156	  void VisitStmt_(const BufferStoreNode *op) final {
157	    scope_.push_back(StmtEntry());
158	    // visit subexpr
159	    StmtExprVisitor::VisitStmt_(op);
160	    // Add write access.
161	    const VarNode *buf = op->buffer->data.get();
162	    auto it = alloc_info_.find(buf);
163	    if (it != alloc_info_.end() && it->second.alloc) {
164	      ICHECK_LT(it->second.level, scope_.size());
165	      if (IsAppropriateSharedMemory(tvm::ffi::GetRef<Var>(buf))) {
166	        // set into scope_.size() - 1 for aggressive memory reuse
167	        auto enable_aggressive_merge = enable_aggressive_merge_;
168	        if (enable_aggressive_merge) {
169	          scope_[scope_.size() - 1].touched.push_back(buf);
170	        } else {
171	          scope_[it->second.level].touched.push_back(buf);
172	        }
173	      }
174	    }
175	
176	    StmtEntry e = scope_.back();
177	    scope_.pop_back();
178	    if (!e.touched.empty()) {
179	      e.stmt = op;
180	      UpdateStmtAttr(op, scope_level_);
181	      linear_seq_.push_back(e);
182	    }
183	  }
184	
185	  void VisitStmt_(const EvaluateNode *op) final {
186	    scope_.push_back(StmtEntry());
187	    // visit subexpr
188	    StmtExprVisitor::VisitStmt_(op);
189	    StmtEntry e = scope_.back();
190	    scope_.pop_back();
191	    if (!e.touched.empty()) {
192	      e.stmt = op;
193	      UpdateStmtAttr(op, scope_level_);
194	      linear_seq_.push_back(e);
195	    }
196	  }
197	
198	  void VisitExpr_(const BufferLoadNode *op) final {
199	    // Add write access.
200	    StmtExprVisitor::VisitExpr_(op);
201	    const VarNode *buf = op->buffer->data.get();
202	    auto it = alloc_info_.find(buf);
203	    if (it != alloc_info_.end() && it->second.alloc) {
204	      // Earlier we required `alloc_level < scope_.size()`, assuming every load
205	      // would occur strictly inside a nested scope.  In practice the lowering
206	      // pipeline may materialise reads in the very same frame that owns the
207	      // allocation (e.g. when the buffer value is passed directly to a call),
208	      // which used to trigger the CHECK.  Treat same-level accesses as valid so
209	      // the merged allocator can reason about their lifetime correctly.
210	      ICHECK_LE(it->second.level, scope_.size())
211	          << "Load memory in places other than store.";
212	      if (IsAppropriateSharedMemory(tvm::ffi::GetRef<Var>(buf))) {
213	        auto enable_aggressive_merge = enable_aggressive_merge_;
214	        if (enable_aggressive_merge) {
215	          scope_[scope_.size() - 1].touched.push_back(buf);
216	        } else {
217	          // When the access happens in the same scope frame as the allocation
218	          // we attribute it to that frame instead of the outer parent.  This
219	          // keeps the liveness window tight while still accounting for nested
220	          // scopes that legitimately touch the buffer deeper in the tree.
221	          size_t access_level = std::min(it->second.level, scope_.size() - 1);
222	          scope_[access_level].touched.push_back(buf);
223	        }
224	      }
225	    }
226	  }
227	
228	  void VisitExpr_(const VarNode *buf) final {
229	    // Directly reference to the variable count as a read.
230	    auto it = alloc_info_.find(buf);
231	    if (it != alloc_info_.end() && it->second.alloc) {
232	      // Same rationale as the BufferLoad path above: direct references can be
233	      // emitted at the allocation level after flattening, so accept them and
234	      // record the touch for liveness planning.
235	      ICHECK_LE(it->second.level, scope_.size());
236	      if (IsAppropriateSharedMemory(tvm::ffi::GetRef<Var>(buf))) {
237	        auto enable_aggressive_merge = enable_aggressive_merge_;
238	        if (enable_aggressive_merge) {
239	          scope_[scope_.size() - 1].touched.push_back(buf);
240	        } else {
241	          // Attribute same-level uses to the allocation frame, mirroring the
242	          // BufferLoad handling to keep reuse decisions consistent.
243	          size_t access_level = std::min(it->second.level, scope_.size() - 1);
244	          scope_[access_level].touched.push_back(buf);
245	        }
246	      }
247	    }
248	  }
249	
250	  template <typename T> void VisitNewScope(const T *op) {
251	    scope_.push_back(StmtEntry());
252	    StmtEntry e;
253	    e.stmt = op;
254	    UpdateStmtAttr(op, scope_level_);
255	    int64_t begin_index = static_cast<int64_t>(linear_seq_.size());
256	    // before scope.
257	    linear_seq_.push_back(e);
258	    StmtExprVisitor::VisitStmt_(op);
259	    // after scope.
260	    e.touched = std::move(scope_.back().touched);
261	    scope_.pop_back();
262	    int64_t end_index = static_cast<int64_t>(linear_seq_.size());
263	    ICHECK_GT(end_index, begin_index);
264	    // The paired entries serve as scope sentinels once we flatten the
265	    // control-flow tree.
266	    e.scope_pair_offset = begin_index - end_index;
267	    linear_seq_.push_back(e);
268	    // record the pointer to end index.
269	    ICHECK_NE(end_index, 0U);
270	    linear_seq_[begin_index].scope_pair_offset = end_index - begin_index;
271	  }
272	
273	  void VisitStmt_(const AttrStmtNode *op) final {
274	    // Only record the outer most thread extent.
275	    if (op->attr_key == tir::attr::thread_extent && !in_thread_env_) {
276	      in_thread_env_ = true;
277	      VisitNewScope(op);
278	      in_thread_env_ = false;
279	    } else if (op->attr_key == tir::attr::extern_scope) {
280	      VisitNewScope(op);
281	    } else if (op->attr_key == tir::attr::virtual_thread) {
282	      VisitNewScope(op);
283	    } else if (op->attr_key == "kWarpSpecializationScope") {
284	      IfThenElse body = Downcast<IfThenElse>(op->body);
285	      this->VisitStmt(body->then_case);
286	      this->VisitStmt(body->else_case.value());
287	    } else {
288	      StmtExprVisitor::VisitStmt_(op);
289	    }
290	  }
291	
292	  void VisitStmt_(const IfThenElseNode *op) final { VisitNewScope(op); }
293	
294	  bool ContainsSeqStmt(const Stmt &stmt) {
295	    if (stmt->IsInstance<SeqStmtNode>()) {
296	      return true;
297	    }
298	    if (const auto *if_node = stmt.as<IfThenElseNode>()) {
299	      return ContainsSeqStmt(if_node->then_case) ||
300	             (if_node->else_case.defined() &&
301	              ContainsSeqStmt(if_node->else_case.value()));
302	    }
303	    return false;
304	  }
305	
306	  void VisitStmt_(const ForNode *op) final {
307	    if (ContainsSeqStmt(op->body)) {
308	      scope_level_++;
309	      VisitNewScope(op);
310	      scope_level_--;
311	    } else {
312	      VisitNewScope(op);
313	    }
314	  }
315	
316	  void VisitStmt_(const WhileNode *op) final { VisitNewScope(op); }
317	
318	  void VisitStmt_(const AssertStmtNode *op) final { VisitNewScope(op); }
319	
320	  // linearized access sequence.
321	  std::vector<StmtEntry> linear_seq_;
322	  // The storage scope of each buffer
323	  std::unordered_map<const VarNode *, AllocEntry> alloc_info_;
324	  // The attribute of each statement
325	  std::unordered_map<const Object *, StmtAttr> stmt_attrs_;
326	
327	private:
328	  // Wrapper function to determine if the shared memory allocation for a
329	  // variable is appropriate.
330	  bool IsAppropriateSharedMemory(const Var &var) {
331	    return is_dynamic_ ? IsDynamicSharedMemory(var) : IsStaticSharedMemory(var);
332	  }
333	  // Whether do dynamic analysis.
334	  bool is_dynamic_{true};
335	  // Whether do aggressive merge.
336	  bool enable_aggressive_merge_{false};
337	  // Whether do verbose logging.
338	  bool verbose_{false};
339	  // Whether already in thread env.
340	  bool in_thread_env_{false};
341	  // The scope stack.
342	  std::vector<StmtEntry> scope_;
343	  // The size of the scope.
344	  size_t scope_level_{0};
345	};
346	
347	class SharedMemoryAlignmentPlanner : public StmtExprVisitor {
348	
349	public:
350	  static std::unordered_map<const VarNode *, int> Plan(const Stmt &stmt) {
351	    SharedMemoryAlignmentPlanner planner;
352	    planner(stmt);
353	    return planner.shmem_alignment_map_;
354	  }
355	
356	private:
357	  // Helper to record alignment for a shared/shared.dyn Var under alignment
358	  // scope
359	  void MarkSharedVarIfNeeded(const VarNode *op) {
360	    if (!op || !under_alignment_scope_)
361	      return;
362	    auto ptr_type = op->type_annotation.as<PointerTypeNode>();
363	    if (!ptr_type)
364	      return;
365	    auto scope = GetPtrStorageScope(tvm::ffi::GetRef<Var>(op));
366	    if (scope == "shared" || scope == "shared.dyn") {
367	      auto target = Target::Current();
368	      ICHECK(target.defined()) << "Target is not defined";
369	      const int alignment = TargetIsHopper(target) ? 1024 : 16;
370	      shmem_alignment_map_[op] = alignment;
371	    }
372	  }
373	
374	  void VisitExpr_(const CallNode *op) {
375	    if (op->op.same_as(tl::tl_gemm()) || op->op.same_as(tl::tl_gemm_sp()) ||
376	        op->op.same_as(tl::tma_load()) || op->op.same_as(tl::tma_store()) ||
377	        op->op.same_as(tl::initialize_wgmma_descriptor()) ||
378	        op->op.same_as(tl::initialize_tcgen05_descriptor())) {
379	      // These intrinsics introduce stricter SMEM alignment requirements; mark
380	      // the subtree.
381	      under_alignment_scope_ = true;
382	      StmtExprVisitor::VisitExpr_(op);
383	      under_alignment_scope_ = false;
384	    } else {
385	      StmtExprVisitor::VisitExpr_(op);
386	    }
387	  }
388	
389	  void VisitExpr_(const VarNode *op) {
390	    MarkSharedVarIfNeeded(op);
391	    StmtExprVisitor::VisitExpr_(op);
392	  }
393	
394	  void VisitExpr_(const BufferLoadNode *op) {
395	    // If we encounter address_of(BufferLoad(...)) or any direct BufferLoad
396	    // within an alignment scope, make sure we mark the underlying shared var.
397	    if (op && under_alignment_scope_) {
398	      const VarNode *data_var = op->buffer->data.get();
399	      MarkSharedVarIfNeeded(data_var);
400	    }
401	    StmtExprVisitor::VisitExpr_(op);
402	  }
403	
404	  bool under_alignment_scope_{false};
405	
406	  std::unordered_map<const VarNode *, int> shmem_alignment_map_;
407	};
408	
409	/*!
410	 * \brief merge the buffers whose live range has no intersection and rewrite the
411	 * body
412	 */
413	class SharedMemoryRewriter : public StmtExprMutator {
414	public:
415	  explicit SharedMemoryRewriter(
416	      const std::unordered_map<const VarNode *, const AllocateNode *>
417	          &shmem_allocs,
418	      bool is_dynamic = true, bool verbose = false, int align_bytes = 0)
419	      : is_dynamic_{is_dynamic}, shmem_allocs_{shmem_allocs}, verbose_{verbose},
420	        align_bytes_{align_bytes} {
421	    if (!is_dynamic) {
422	      merged_buf_var_ =
423	          Var("buf_shmem", PointerType(PrimType(DataType::UInt(8)), "shared"));
424	    }
425	  }
426	
427	  /*!
428	   * \brief plan the memory reuse for all the buffer allocated in the statement
429	   * \param stmt the statement
430	   */
431	  void PlanReuse(const Stmt &stmt, bool is_dynamic = true,
432	                 bool enable_aggressive_merge = false, bool verbose = false) {
433	    SharedMemLinearAccessPatternFinder finder(is_dynamic,
434	                                              enable_aggressive_merge, verbose);
435	    finder(stmt);
436	    shmem_alignment_map_ = SharedMemoryAlignmentPlanner::Plan(stmt);
437	    // First compute liveness over the flattened schedule, then feed it into the
438	    // arena packer.
439	    this->LivenessAnalysis(finder.linear_seq_, finder.stmt_attrs_);
440	    this->PlanMemory(finder.linear_seq_, finder.stmt_attrs_);
441	  }
442	
443	private:
444	  Stmt VisitStmt_(const AttrStmtNode *op) final {
445	    if (op->attr_key == tir::attr::thread_extent && !allocated_) {
446	      // Allocate one dynamic shared memory allocation at the beginning of
447	      // thread scope
448	
449	      if (verbose_) {
450	
451	        LOG(DEBUG) << "Memory Allocation Plan for "
452	                   << (is_dynamic_ ? "Dynamic" : "Static") << " Shared Memory:";
453	        LOG(DEBUG) << "  Merged Buffer Name: " << merged_buf_var_->name_hint;
454	        LOG(DEBUG) << "  Total Merged Size: " << merged_alloc_size_ << " bytes";
455	        LOG(DEBUG) << "  Individual Buffer Allocations:";
456	        for (const auto &pair : buffer_byte_offsets_) {
457	          const VarNode *buffer_var_node = pair.first;
458	          PrimExpr byte_offset = pair.second;
459	          auto alloc_it = shmem_allocs_.find(buffer_var_node);
460	          if (alloc_it != shmem_allocs_.end()) {
461	            const AllocateNode *alloc = alloc_it->second;
462	            PrimExpr buffer_size_bytes =
463	                alloc->extents[0] * alloc->dtype.bytes() * alloc->dtype.lanes();
464	            LOG(DEBUG) << "    Buffer: " << buffer_var_node->name_hint
465	                       << " (Type: " << alloc->dtype << ")"
466	                       << ", Start Offset: " << byte_offset
467	                       << ", Size: " << buffer_size_bytes << " bytes"
468	                       << ", End Offset: "
469	                       << (byte_offset + buffer_size_bytes - 1);
470	          } else {
471	            LOG(DEBUG) << "    Buffer: " << buffer_var_node->name_hint
472	                       << ", Start Offset: " << byte_offset
473	                       << " (Original allocation info not found)";
474	          }
475	        }
476	        LOG(DEBUG) << "End of Memory Allocation Plan.";
477	      }
478	
479	      allocated_ = true;
480	      Allocate new_body(merged_buf_var_, DataType::UInt(8),
481	                        {merged_alloc_size_}, const_true(),
482	                        StmtExprMutator::VisitStmt(op->body));
483	      return AttrStmt(op->node, op->attr_key, op->value, new_body, op->span);
484	    }
485	    return StmtMutator::VisitStmt_(op);
486	  }
