518	          << "and is to be run after "
519	          << "StorageFlatten (TE schedules) or FlattenBuffer (TIR schedules)";
520	      Array<PrimExpr> indices = {
521	          node->indices[0] +
522	          this->GetBufferOffset(node->buffer->data, node->buffer->dtype)};
523	
524	      auto writer = node.CopyOnWrite();
525	      writer->buffer = GetUpdatedBuffer(node->buffer);
