540	      ICHECK_EQ(buffer->shape.size(), 1)
541	          << "Buffer " << buffer << " has shape " << buffer->shape << ".  "
542	          << "MergeSharedMemoryAllocations expects flat memory buffers, "
543	          << "and is to be run after "
544	          << "StorageFlatten (TE schedules) or FlattenBuffer (TIR schedules)";
