553	  PrimExpr VisitExpr_(const CallNode *op) final {
554	    if (op->op.same_as(builtin::tvm_access_ptr())) {
555	      ICHECK_EQ(op->args.size(), 5U);
556	      DataType dtype = op->args[0].dtype();
557	      Var buffer = Downcast<Var>(op->args[1]);
558	      if (!IsAppropriateSharedMemory(buffer)) {
559	        return StmtExprMutator::VisitExpr_(op);
560	      }
561	      PrimExpr extra_offset = GetBufferOffset(buffer, dtype);
562	
563	      PrimExpr offset = this->VisitExpr(op->args[2]);
564	      PrimExpr extent = this->VisitExpr(op->args[3]);
565	      return Call(op->dtype, op->op,
566	                  {op->args[0], merged_buf_var_, extra_offset + offset, extent,
567	                   op->args[4]});
568	    } else if (op->op.same_as(builtin::ptx_cp_async())) {
569	      ICHECK((op->args.size() == 5U) || (op->args.size() == 6U));
570	      DataType dtype = op->dtype;
571	      Var buffer = Downcast<Var>(op->args[0]);
572	      if (!IsAppropriateSharedMemory(buffer)) {
573	        return StmtExprMutator::VisitExpr_(op);
574	      }
575	      PrimExpr extra_offset = GetBufferOffset(buffer, dtype);
576	      PrimExpr offset = this->VisitExpr(op->args[1]);
577	      // the dst shared memory is a byte buffer generated by merging shared
578	      // memory. we need to multiply the offset index by the byte size of the
579	      // original value dtype, to get the correct offset of merged shared
580	      // buffer.
581	      int index_factor = dtype.bytes();
582	      if (op->args.size() == 5)
583	        return Call(dtype, op->op,
584	                    {merged_buf_var_,
585	                     mul(extra_offset + offset, PrimExpr(index_factor)),
586	                     op->args[2], op->args[3], op->args[4]});
587	      else
588	        return Call(dtype, op->op,
589	                    {merged_buf_var_,
590	                     mul(extra_offset + offset, PrimExpr(index_factor)),
591	                     op->args[2], op->args[3], op->args[4], op->args[5]});
592	    } else {
593	      return StmtExprMutator::VisitExpr_(op);
594	    }
595	  }
