641	
642	  static size_t AlignUpSize(size_t value, size_t alignment) {
643	    if (alignment == 0) {
644	      return value;
645	    }
646	    size_t remainder = value % alignment;
647	    if (remainder == 0) {
648	      return value;
649	    }
650	    return value + (alignment - remainder);
651	  }
