653	  struct FreeBlock {
654	    size_t offset{0};
655	    size_t size{0};
656	  };
657	
658	  class FreeList {
659	  public:
660	    std::optional<size_t> Allocate(size_t need, size_t alignment) {
661	      // Best-fit search: pick the slot that wastes the least space after
662	      // alignment.
663	      int best = -1;
664	      size_t best_waste = std::numeric_limits<size_t>::max();
665	      for (int i = 0, n = static_cast<int>(blocks_.size()); i < n; ++i) {
666	        size_t aligned = AlignUpSize(blocks_[i].offset, alignment);
667	        size_t head = aligned - blocks_[i].offset;
668	        if (head <= blocks_[i].size && (blocks_[i].size - head) >= need) {
669	          size_t waste = blocks_[i].size - head - need;
670	          if (waste < best_waste) {
671	            best_waste = waste;
672	            best = i;
673	          }
674	        }
675	      }
676	      if (best < 0) {
677	        return std::nullopt;
678	      }
679	      FreeBlock blk = blocks_[best];
680	      size_t aligned = AlignUpSize(blk.offset, alignment);
681	      size_t head = aligned - blk.offset;
682	      size_t tail = blk.size - head - need;
683	      blocks_.erase(blocks_.begin() + best);
684	      if (head) {
685	        blocks_.push_back({blk.offset, head});
686	      }
687	      if (tail) {
688	        blocks_.push_back({aligned + need, tail});
689	      }
690	      Normalize();
691	      return aligned;
692	    }
693	
694	    void Free(size_t offset, size_t size) {
695	      if (size == 0)
696	        return;
697	      blocks_.push_back({offset, size});
698	      Normalize();
699	    }
700	
701	  private:
702	    void Normalize() {
703	      if (blocks_.empty())
704	        return;
705	      std::sort(blocks_.begin(), blocks_.end(),
706	                [](const FreeBlock &a, const FreeBlock &b) {
707	                  return a.offset < b.offset;
708	                });
709	      std::vector<FreeBlock> merged;
710	      merged.reserve(blocks_.size());
711	      for (const FreeBlock &blk : blocks_) {
712	        if (merged.empty()) {
713	          merged.push_back(blk);
714	          continue;
715	        }
716	        FreeBlock &last = merged.back();
717	        size_t last_end = last.offset + last.size;
718	        if (blk.offset <= last_end) {
719	          size_t blk_end = blk.offset + blk.size;
720	          if (blk_end > last_end) {
721	            last.size = blk_end - last.offset;
722	          }
723	        } else {
724	          merged.push_back(blk);
725	        }
726	      }
727	      blocks_ = std::move(merged);
728	    }
729	
730	    std::vector<FreeBlock> blocks_;
731	  };
732	
733	  struct ActiveInterval {
734	    int end{0};
735	    size_t offset{0};
736	    size_t size{0};
737	    const VarNode *var{nullptr};
738	    bool operator>(const ActiveInterval &other) const {
739	      return end > other.end;
740	    }
741	  };
742	
743	  static ArenaPlan LinearScanPack(std::vector<Interval> intervals) {
744	    // Process intervals in program order so lifetimes correspond to the
745	    // linearised CFG.
746	    std::sort(intervals.begin(), intervals.end(),
747	              [](const Interval &lhs, const Interval &rhs) {
748	                if (lhs.start != rhs.start) {
749	                  return lhs.start < rhs.start;
750	                }
751	                if (lhs.size_bytes != rhs.size_bytes) {
752	                  return lhs.size_bytes > rhs.size_bytes;
753	                }
754	                // Use name comparison for deterministic ordering instead of
755	                // pointer comparison
756	                return lhs.var->name_hint < rhs.var->name_hint;
757	              });
758	
759	    std::priority_queue<ActiveInterval, std::vector<ActiveInterval>,
760	                        std::greater<ActiveInterval>>
761	        active;
762	    FreeList freelist;
763	    size_t arena_top = 0;
764	    std::unordered_map<const VarNode *, size_t> offsets;
765	
766	    // Expire intervals that end before or at program counter `pc`.
767	    auto retire = [&](int pc) {
768	      while (!active.empty() && active.top().end <= pc) {
769	        const ActiveInterval top = active.top();
770	        active.pop();
771	        freelist.Free(top.offset, top.size);
772	      }
773	    };
774	
775	    for (const Interval &interval : intervals) {
776	      retire(interval.start);
777	      size_t offset = 0;
778	      // Try to recycle previously freed memory first; fall back to bumping the
779	      // arena.
780	      if (auto slot =
781	              freelist.Allocate(interval.size_bytes, interval.alignment)) {
782	        offset = slot.value();
783	      } else {
784	        offset = AlignUpSize(arena_top, interval.alignment);
785	        arena_top = offset + interval.size_bytes;
786	      }
787	      active.push(ActiveInterval{interval.end, offset, interval.size_bytes,
788	                                 interval.var});
789	      offsets[interval.var] = offset;
790	    }
791	
792	    return ArenaPlan{arena_top, std::move(offsets)};
793	  }
794	
795	  PrimExpr AlignPrimExpr(const PrimExpr &value, int alignment) const {
796	    if (alignment <= 1) {
797	      return value;
798	    }
799	    DataType dtype = value.dtype();
800	    ICHECK(dtype.is_int() || dtype.is_uint())
801	        << "Expected integer dtype for alignment, but got " << dtype;
802	    PrimExpr align_expr = make_const(dtype, alignment);
803	    PrimExpr adjust = make_const(dtype, alignment - 1);
804	    return indexdiv(value + adjust, align_expr) * align_expr;
805	  }
