827	  /*!
828	   * \brief Liveness analysis to find gen and kill point of each variable.
829	   * \param seq the linear pattern of storage access
830	   */
831	  void LivenessAnalysis(
832	      const std::vector<StmtEntry> &seq,
833	      const std::unordered_map<const Object *, StmtAttr> &stmt_attrs) {
834	    // find kill point, do a reverse linear scan.
835	    std::unordered_set<const VarNode *> touched;
836	    for (size_t i = seq.size(); i != 0; --i) {
837	      const StmtEntry &s = seq[i - 1];
838	      for (const VarNode *buffer : s.touched) {
839	        if (!touched.count(buffer)) {
840	          touched.insert(buffer);
841	          event_map_[s.stmt].kill.push_back(buffer);
842	        }
843	      }
844	    }
845	    // find gen point, do forward scan
846	    touched.clear();
847	    for (size_t i = 0; i < seq.size(); ++i) {
848	      int64_t offset = seq[i].scope_pair_offset;
849	      if (offset < 0)
850	        continue;
851	      const StmtEntry &s = seq[i + offset];
852	      for (const VarNode *buffer : s.touched) {
853	        if (!touched.count(buffer)) {
854	          touched.insert(buffer);
855	          event_map_[s.stmt].gen.push_back(buffer);
856	        }
857	      }
858	    }
859	
860	    if (verbose_) {
861	      std::vector<const Object *> stmt_keys;
862	      for (const auto &stmt_entry : seq) {
863	        auto stmt = stmt_entry.stmt;
864	        if (std::find(stmt_keys.begin(), stmt_keys.end(), stmt) ==
865	            stmt_keys.end()) {
866	          stmt_keys.push_back(stmt);
867	        }
868	      }
869	      LOG(DEBUG) << "Before reorder kill points, Liveness Analysis Results for "
870	                 << (is_dynamic_ ? "Dynamic" : "Static") << " Shared Memory:";
871	      for (const auto &stmt_key : stmt_keys) {
872	        auto it = event_map_.find(stmt_key);
873	        if (it == event_map_.end())
874	          continue;
875	
876	        const EventEntry &entry = it->second;
877	        if (entry.gen.empty() && entry.kill.empty())
878	          continue;
879	        ICHECK(stmt_attrs.count(stmt_key))
880	            << "stmt_key = " << stmt_key->GetTypeKey();
881	        auto level = stmt_attrs.at(stmt_key).level;
882	        LOG(DEBUG) << "  Statement: " << stmt_key->GetTypeKey()
883	                   << " (scope_level: " << level << ")";
884	
885	        std::stringstream gen_vars_ss;
886	        bool x_generated = false;
887	        for (const VarNode *var : entry.gen) {
888	          gen_vars_ss << var->name_hint << " ";
889	          if (var->name_hint == "x") {
890	            x_generated = true;
891	          }
892	        }
893	        if (!entry.gen.empty()) {
894	          std::string gen_log_msg = "    GEN: " + gen_vars_ss.str();
895	          if (x_generated) {
896	            gen_log_msg += " <-- Buffer 'x' generated";
897	          }
898	          LOG(DEBUG) << gen_log_msg;
899	        }
900	
901	        std::stringstream kill_vars_ss;
902	        bool x_killed = false;
903	        for (const VarNode *var : entry.kill) {
904	          kill_vars_ss << var->name_hint << " ";
905	          if (var->name_hint == "x") {
906	            x_killed = true;
907	          }
908	        }
909	        if (!entry.kill.empty()) {
910	          std::string kill_log_msg = "    KILL: " + kill_vars_ss.str();
911	          if (x_killed) {
912	            kill_log_msg += " <-- Buffer 'x' killed";
913	          }
914	          LOG(DEBUG) << kill_log_msg;
915	        }
916	      }
917	      LOG(DEBUG) << "End of Liveness Analysis Results.";
918	    }
919	
920	    // Reorder kill points:
921	    // For each buffer, if its kill statement is at a deeper scope level than
922	    // its gen statement, we need to move the kill point to the end of the gen
923	    // statement's scope level. This ensures proper memory deallocation at the
924	    // right scope boundary.
925	    std::vector<StmtEntry> gen_kill_seq;
926	    for (const auto &stmt_entry : seq) {
927	      // if has gen and kill, add to gen_kill_seq
928	      if (!event_map_[stmt_entry.stmt].gen.empty() ||
929	          !event_map_[stmt_entry.stmt].kill.empty()) {
930	        gen_kill_seq.push_back(stmt_entry);
931	      }
932	    }
933	
934	    for (auto &event_pair : event_map_) {
935	      const Object *stmt = event_pair.first;
936	      EventEntry &event = event_pair.second;
937	
938	      // Skip if no kill points to process
939	      if (event.kill.empty())
940	        continue;
941	
942	      // Get scope level of current statement
943	      ICHECK(stmt_attrs.count(stmt));
944	      int kill_level = stmt_attrs.at(stmt).level;
945	
946	      std::unordered_set<const VarNode *> visited_buffers;
947	
948	      // For each killed buffer, find its gen statement and check scope levels
949	      for (auto it = event.kill.begin(); it != event.kill.end();) {
950	        const VarNode *buffer = *it;
951	        bool found_gen = false;
952	        int gen_level = 0;
953	
954	        // Find the gen statement for this buffer
955	        for (const auto &gen_pair : event_map_) {
956	          const auto &gen_event = gen_pair.second;
957	          if (std::find(gen_event.gen.begin(), gen_event.gen.end(), buffer) !=
958	              gen_event.gen.end()) {
959	            found_gen = true;
960	            gen_level = stmt_attrs.at(gen_pair.first).level;
961	            break;
962	          }
963	        }
964	
965	        if (found_gen && kill_level > gen_level) {
966	          if (visited_buffers.count(buffer)) {
967	            ++it;
968	            continue;
969	          }
970	          // Need to move kill point - remove from current event
971	          it = event.kill.erase(it);
972	
973	          // Find the last statement at gen_level and add kill point there
974	          // Find the last statement at gen_level in the sequence
975	          const Object *last_stmt_at_level = nullptr;
976	          auto stmt_it = gen_kill_seq.begin();
977	          for (; stmt_it != gen_kill_seq.end(); ++stmt_it) {
978	            if (stmt_it->stmt == stmt) {
979	              break;
980	            }
981	          }
982	          // start from current statement and find the last statement at
983	          // gen_level
984	
985	          for (; stmt_it != gen_kill_seq.end(); ++stmt_it) {
986	            // Check if next statement has different level
987	            auto next_it = stmt_it + 1;
988	            if (next_it == gen_kill_seq.end() ||
989	                stmt_attrs.at(next_it->stmt).level == gen_level) {
990	              last_stmt_at_level = stmt_it->stmt;
991	              break;
992	            }
993	          }
994	          if (last_stmt_at_level) {
995	            event_map_[last_stmt_at_level].kill.push_back(buffer);
996	            visited_buffers.insert(buffer);
997	          }
998	        } else {
999	          ++it;
1000	        }
1001	      }
1002	    }
1003	
1004	    std::vector<const Object *> stmt_keys;
1005	    for (const auto &stmt_entry : seq) {
1006	      auto stmt = stmt_entry.stmt;
1007	      if (std::find(stmt_keys.begin(), stmt_keys.end(), stmt) ==
1008	          stmt_keys.end()) {
1009	        stmt_keys.push_back(stmt);
1010	      }
1011	    }
1012	
1013	    if (verbose_) {
1014	      LOG(DEBUG) << "Liveness Analysis Results for "
1015	                 << (is_dynamic_ ? "Dynamic" : "Static") << " Shared Memory:";
1016	      for (const auto &stmt_key : stmt_keys) {
1017	        auto it = event_map_.find(stmt_key);
1018	        if (it == event_map_.end())
1019	          continue;
1020	
1021	        const EventEntry &entry = it->second;
1022	        if (entry.gen.empty() && entry.kill.empty())
1023	          continue;
1024	        ICHECK(stmt_attrs.count(stmt_key))
1025	            << "stmt_key = " << stmt_key->GetTypeKey();
1026	        auto level = stmt_attrs.at(stmt_key).level;
1027	        LOG(DEBUG) << "  Statement: " << stmt_key->GetTypeKey()
1028	                   << " (scope_level: " << level << ")";
1029	
1030	        std::stringstream gen_vars_ss;
1031	        bool x_generated = false;
1032	        for (const VarNode *var : entry.gen) {
1033	          gen_vars_ss << var->name_hint << " ";
1034	          if (var->name_hint == "x") {
1035	            x_generated = true;
1036	          }
1037	        }
1038	        if (!entry.gen.empty()) {
1039	          std::string gen_log_msg = "    GEN: " + gen_vars_ss.str();
1040	          if (x_generated) {
1041	            gen_log_msg += " <-- Buffer 'x' generated";
1042	          }
1043	          LOG(DEBUG) << gen_log_msg;
1044	        }
1045	
1046	        std::stringstream kill_vars_ss;
1047	        bool x_killed = false;
1048	        for (const VarNode *var : entry.kill) {
1049	          kill_vars_ss << var->name_hint << " ";
1050	          if (var->name_hint == "x") {
1051	            x_killed = true;
1052	          }
1053	        }
1054	        if (!entry.kill.empty()) {
1055	          std::string kill_log_msg = "    KILL: " + kill_vars_ss.str();
1056	          if (x_killed) {
1057	            kill_log_msg += " <-- Buffer 'x' killed";
1058	          }
1059	          LOG(DEBUG) << kill_log_msg;
1060	        }
1061	      }
1062	      LOG(DEBUG) << "End of Liveness Analysis Results.";
1063	    }
1064	  }
1065	
1066	  /*!
1067	   * \brief Memory plan algorithm
1068	   * \param seq the linear pattern of storage access
1069	   * \param alloc_info
1070	   */
1071	  void
1072	  PlanMemory(const std::vector<StmtEntry> &seq,
1073	             const std::unordered_map<const Object *, StmtAttr> &stmt_attrs) {
1074	    buffer_byte_offsets_.clear();
1075	    (void)stmt_attrs;
1076	
1077	    if (shmem_allocs_.empty()) {
1078	      merged_alloc_size_ = make_const(DataType::Int(64), 0);
1079	      return;
1080	    }
1081	
1082	    // Discover the first and last touch for every allocation.
1083	    std::unordered_map<const VarNode *, int> start_index;
1084	    std::unordered_map<const VarNode *, int> end_index;
1085	
1086	    for (size_t i = 0; i < seq.size(); ++i) {
1087	      auto it = event_map_.find(seq[i].stmt);
1088	      if (it == event_map_.end())
1089	        continue;
1090	      for (const VarNode *var : it->second.gen) {
1091	        start_index.emplace(var, static_cast<int>(i));
1092	      }
1093	      for (const VarNode *var : it->second.kill) {
1094	        end_index[var] = std::max(end_index[var], static_cast<int>(i) + 1);
1095	      }
1096	    }
1097	
1098	    const int seq_len = static_cast<int>(seq.size());
1099	    for (const auto &kv : start_index) {
1100	      if (!end_index.count(kv.first)) {
1101	        end_index[kv.first] = seq_len;
1102	      }
1103	    }
1104	
1105	    // Create a sorted vector of keys from shmem_allocs_ for deterministic
1106	    // iteration
1107	    std::vector<const VarNode *> sorted_vars;
1108	    sorted_vars.reserve(shmem_allocs_.size());
1109	    for (const auto &kv : shmem_allocs_) {
1110	      sorted_vars.push_back(kv.first);
1111	    }
1112	    std::sort(sorted_vars.begin(), sorted_vars.end(),
1113	              [](const VarNode *a, const VarNode *b) {
1114	                return a->name_hint < b->name_hint;
1115	              });
1116	
1117	    std::vector<BufInfo> buf_infos;
1118	    buf_infos.reserve(shmem_allocs_.size());
1119	    // Build a BufInfo for all allocations that participate in liveness.
1120	    for (const VarNode *var : sorted_vars) {
1121	      auto start_it = start_index.find(var);
1122	      if (start_it == start_index.end()) {
1123	        continue;
1124	      }
1125	
1126	      BufInfo info;
1127	      info.var = var;
1128	      info.name = var->name_hint;
1129	      info.start = start_it->second;
1130	      info.end = std::max(end_index[var], info.start + 1);
1131	      info.alignment = align_bytes_;
1132	      auto align_it = shmem_alignment_map_.find(var);
1133	      if (align_it != shmem_alignment_map_.end()) {
1134	        info.alignment = std::max(info.alignment, align_it->second);
1135	      }
1136	
1137	      const AllocateNode *alloc = shmem_allocs_.at(var);
1138	      int64_t bytes_per_elem =
1139	          static_cast<int64_t>(alloc->dtype.bytes() * alloc->dtype.lanes());
1140	      DataType size_dtype = DataType::Int(32);
1141	      if (!alloc->extents.empty()) {
1142	        size_dtype = alloc->extents[0].dtype();
1143	      }
1144	      if (!size_dtype.is_int() && !size_dtype.is_uint()) {
1145	        size_dtype = DataType::Int(32);
1146	      }
1147	
1148	      PrimExpr size_expr = make_const(size_dtype, bytes_per_elem);
1149	      for (const PrimExpr &extent : alloc->extents) {
1150	        PrimExpr e = extent;
1151	        if (e.dtype() != size_dtype) {
1152	          e = cast(size_dtype, e);
1153	        }
1154	        size_expr = size_expr * e;
1155	      }
1156	      info.size_dtype = size_dtype;
1157	      info.size_expr = size_expr;
1158	
1159	      int64_t const_extent = alloc->ConstantAllocationSize();
1160	      if (const_extent >= 0) {
1161	        info.const_size_bytes = const_extent * bytes_per_elem;
1162	      }
1163	
1164	      buf_infos.push_back(std::move(info));
1165	    }
1166	
1167	    // Stable order so the later passes have deterministic behaviour.
1168	    std::sort(buf_infos.begin(), buf_infos.end(),
1169	              [](const BufInfo &a, const BufInfo &b) {
1170	                if (a.start != b.start)
1171	                  return a.start < b.start;
1172	                if (a.end != b.end)
1173	                  return a.end < b.end;
1174	                return a.name < b.name;
1175	              });
1176	
1177	    std::vector<Interval> intervals;
1178	    intervals.reserve(buf_infos.size());
1179	    for (const BufInfo &info : buf_infos) {
1180	      if (!info.const_size_bytes.has_value())
1181	        continue;
1182	      // Only constant-sized buffers participate in the arena packing because
1183	      // dynamic sizes must be placed sequentially later.
1184	      Interval interval;
1185	      interval.start = info.start;
1186	      interval.end = info.end;
1187	      interval.size_bytes = static_cast<size_t>(
1188	          std::max<int64_t>(0, info.const_size_bytes.value()));
1189	      interval.alignment = info.alignment;
1190	      interval.var = info.var;
1191	      intervals.push_back(interval);
1192	    }
1193	
1194	    ArenaPlan plan = LinearScanPack(std::move(intervals));
1195	    size_t arena_size_const = plan.arena_size;
1196	
1197	    if (verbose_) {
1198	      LOG(DEBUG) << "ArenaPlan (constant buffers): arena_size="
1199	                 << arena_size_const;
1200	      for (const auto &kv : plan.offsets) {
1201	        const VarNode *var = kv.first;
1202	        LOG(DEBUG) << "  " << var->name_hint << " -> offset=" << kv.second;
1203	      }
1204	    }
1205	
1206	    // Cursor tracks the running byte offset within the merged arena.
1207	    DataType offset_dtype =
1208	        buf_infos.empty() ? DataType::Int(32) : buf_infos.front().size_dtype;
1209	    PrimExpr total_size = make_const(offset_dtype, 0);
1210	    PrimExpr cursor = AlignPrimExpr(
1211	        make_const(offset_dtype, static_cast<int64_t>(arena_size_const)),
1212	        align_bytes_);
1213	
1214	    auto CastToOffset = [&](PrimExpr expr) -> PrimExpr {
1215	      if (expr.dtype() == offset_dtype) {
1216	        return expr;
1217	      }
1218	      return cast(offset_dtype, expr);
1219	    };
1220	
1221	    for (const BufInfo &info : buf_infos) {
1222	      PrimExpr offset_expr;
1223	      auto it = plan.offsets.find(info.var);
1224	      if (it != plan.offsets.end()) {
1225	        offset_expr =
1226	            make_const(offset_dtype, static_cast<int64_t>(it->second));
1227	      } else {
1228	        // Dynamic-sized buffers are appended after the constant arena.
1229	        cursor = AlignPrimExpr(cursor, info.alignment);
1230	        PrimExpr size_expr = CastToOffset(info.size_expr);
1231	        offset_expr = cursor;
1232	        cursor = offset_expr + size_expr;
1233	      }
1234	
1235	      buffer_byte_offsets_[info.var] = offset_expr;
1236	      PrimExpr buf_end = offset_expr + CastToOffset(info.size_expr);
1237	      total_size = max(total_size, buf_end);
1238	    }
1239	
1240	    merged_alloc_size_ = buf_infos.empty()
1241	                             ? make_const(offset_dtype, 0)
1242	                             : AlignPrimExpr(total_size, align_bytes_);
1243	
1244	    bool overlap_detected = false;
1245	
1246	    if (verbose_) {
1247	      LOG(DEBUG) << "Memory Allocation Plan for "
1248	                 << (is_dynamic_ ? "Dynamic" : "Static") << " Shared Memory:";
1249	      LOG(DEBUG) << "  Total Merged Size (aligned): " << merged_alloc_size_;
1250	      for (const BufInfo &info : buf_infos) {
1251	        const PrimExpr &offset = buffer_byte_offsets_.at(info.var);
1252	        LOG(DEBUG) << "    Buffer: " << info.name << " start=" << info.start
1253	                   << " end=" << info.end << " alignment=" << info.alignment
1254	                   << " offset=" << offset << " size=" << info.size_expr;
1255	      }
1256	      // Sanity check for overlapping constant buffers.
1257	      for (size_t i = 0; i < buf_infos.size(); ++i) {
1258	        const BufInfo &a = buf_infos[i];
1259	        auto a_off_imm = buffer_byte_offsets_.at(a.var).as<IntImmNode>();
1260	        if (!a.const_size_bytes.has_value() || a_off_imm == nullptr)
1261	          continue;
1262	        int64_t a_off = a_off_imm->value;
1263	        int64_t a_end = a_off + a.const_size_bytes.value();
1264	        for (size_t j = i + 1; j < buf_infos.size(); ++j) {
1265	          const BufInfo &b = buf_infos[j];
1266	          auto b_off_imm = buffer_byte_offsets_.at(b.var).as<IntImmNode>();
1267	          if (!b.const_size_bytes.has_value() || b_off_imm == nullptr)
1268	            continue;
1269	          bool live_overlap = !(a.end <= b.start || b.end <= a.start);
1270	          if (!live_overlap)
1271	            continue;
1272	          int64_t b_off = b_off_imm->value;
1273	          int64_t b_end = b_off + b.const_size_bytes.value();
1274	          bool mem_overlap = !(a_end <= b_off || b_end <= a_off);
1275	          if (mem_overlap) {
1276	            overlap_detected = true;
1277	            LOG(WARNING) << "Buffer overlap detected between " << a.name
1278	                         << " and " << b.name << " (lifetime overlap with "
1279	                         << "offset ranges [" << a_off << ", " << a_end
1280	                         << ") and [" << b_off << ", " << b_end << ")).";
1281	          }
1282	        }
1283	      }
1284	    }
1285	
1286	    if (overlap_detected) {
1287	      LOG(WARNING) << "Detected overlapping constant buffers; falling back to "
1288	                   << "sequential allocation without reuse.";
1289	      buffer_byte_offsets_.clear();
1290	      // In the fallback path we simply lay buffers out sequentially.
1291	      PrimExpr new_cursor = make_const(offset_dtype, 0);
1292	      PrimExpr new_total = make_const(offset_dtype, 0);
1293	      for (const BufInfo &info : buf_infos) {
1294	        new_cursor = AlignPrimExpr(new_cursor, info.alignment);
1295	        PrimExpr size_expr = CastToOffset(info.size_expr);
1296	        buffer_byte_offsets_[info.var] = new_cursor;
1297	        PrimExpr buf_end = new_cursor + size_expr;
1298	        new_total = max(new_total, buf_end);
1299	        new_cursor = buf_end;
1300	      }
1301	      merged_alloc_size_ = buf_infos.empty()
1302	                               ? make_const(offset_dtype, 0)
1303	                               : AlignPrimExpr(new_total, align_bytes_);
1304	    }
1305	  }
1306	
1307	  // Whether enable dynamic analysis.
1308	  bool is_dynamic_{true};
1309	
1310	  // Whether enable verbose logging.
1311	  bool verbose_{false};
1312	  // The alignment bytes for the merged buffer
1313	  int align_bytes_{16};
1314	  // The var for the merged buffer
1315	  Var merged_buf_var_{"buf_dyn_shmem",
1316	                      PointerType(PrimType(DataType::UInt(8)), "shared.dyn")};
1317	  // The mapping from the original buffer var to its allocate
1318	  std::unordered_map<const VarNode *, const AllocateNode *> shmem_allocs_;
1319	  // The size of the merged buffer
1320	  PrimExpr merged_alloc_size_{0};
1321	  // The mapping from the original buffer var to its offset in the merged buffer
1322	  std::unordered_map<const VarNode *, PrimExpr> buffer_byte_offsets_;
1323	  // The mapping from the original buffer objects to their location in the
1324	  // merged buffer.
1325	  std::unordered_map<const BufferNode *, Buffer> buffer_remap_;
1326	  // The flag indicating whether the merged buffer has been allocated
1327	  bool allocated_{false};
1328	  // Locations of free ops.
1329	  std::unordered_map<const Object *, EventEntry> event_map_;
1330	  // The mapping of buffer bytes alignment
1331	  std::unordered_map<const VarNode *, int> shmem_alignment_map_;
1332	};
1333	
1334	Stmt MergeSharedMemoryAllocations(Stmt stmt, bool merge_static_smem,
1335	                                  bool enable_aggressive_merge,
1336	                                  int align_bytes = 16, bool verbose = false) {
1337	  AllocateCollector collector;
1338	  collector(stmt);
1339	  if (collector.dyn_shmem_allocs_.size() > 1) {
1340	    SharedMemoryRewriter rewriter(collector.dyn_shmem_allocs_, true, verbose,
1341	                                  align_bytes);
1342	    rewriter.PlanReuse(stmt, true, enable_aggressive_merge);
1343	    stmt = rewriter(std::move(stmt));
1344	  }
1345	  if (merge_static_smem && collector.static_shmem_allocs_.size() > 1) {
1346	    SharedMemoryRewriter rewriter(collector.static_shmem_allocs_, false,
1347	                                  verbose, align_bytes);
1348	    rewriter.PlanReuse(stmt, false, enable_aggressive_merge);
1349	    stmt = rewriter(std::move(stmt));
1350	  }
1351	  return stmt;
1352	}
1353	
1354	using namespace tir::transform;
1355	
1356	namespace transform {
1357	
1358	Pass MergeSharedMemoryAllocations(bool enable_aggressive_merge = false,
1359	                                  int align_bytes = 16) {
1360	  auto pass_func = [enable_aggressive_merge, align_bytes](
1361	                       PrimFunc f, const IRModule &m, PassContext ctx) {
1362	    bool merge_static_smem =
1363	        ctx->GetConfig<Bool>("tir.merge_static_smem", Bool(false)).value();
1364	    bool debug_merge_shared_memory_allocations =
1365	        ctx->GetConfig<Bool>(kDebugMergeSharedMemoryAllocations, Bool(false))
1366	            .value();
1367	    auto *n = f.CopyOnWrite();
1368	    n->body = tl::MergeSharedMemoryAllocations(
1369	        std::move(n->body), merge_static_smem, enable_aggressive_merge,
1370	        align_bytes, debug_merge_shared_memory_allocations);
1371	    return f;
1372	  };
1373	  return CreatePrimFuncPass(pass_func, 0, "tl.MergeSharedMemoryAllocations",
1374	                            {});
1375	}
1376	
1377	TVM_FFI_STATIC_INIT_BLOCK() {
1378	  namespace refl = tvm::ffi::reflection;
1379	  refl::GlobalDef().def("tl.transform.MergeSharedMemoryAllocations",
1380	                        MergeSharedMemoryAllocations);
1381	}
1382	
1383	} // namespace transform
1384	} // namespace tl
1385	} // namespace tvm
