40	#include "tir/transforms/ir_utils.h"
41	
42	namespace tvm {
43	namespace tl {
44	
45	using namespace tir;
46	using arith::IRMutatorWithAnalyzer;
47	
48	class TileLangThreadSyncPlanner : public TileLangStorageAccessVisitor {
49	public:
50	  explicit TileLangThreadSyncPlanner(StorageScope sync_scope)
51	      : sync_scope_(std::move(sync_scope)) {}
52	
53	  // The syncs inserted before each statement
54	  std::unordered_set<const Object *> syncs_inserted_;
55	
56	protected:
57	  bool Enabled(const VarNode *buf, const StorageScope &scope) const final {
58	    return in_device_env() && scope == sync_scope_;
59	  }
60	  // Plan the sync
61	  std::vector<AccessEntry> Summarize(std::vector<StmtEntry> seq,
62	                                     const ForNode *loop) final {
63	    // Redirect all "shared.dyn" buffer access to the same buffer var
64	    // so that the accesses can be planned together.
65	    Var shared_dyn_buf;
66	    for (StmtEntry &entry : seq) {
67	      for (AccessEntry &access : entry.access) {
68	        if (access.scope.rank == StorageRank::kShared &&
69	            access.scope.tag == ".dyn" && access.buffer.defined()) {
70	          if (!shared_dyn_buf.defined()) {
71	            shared_dyn_buf = access.buffer;
72	          } else {
73	            access.buffer = shared_dyn_buf;
74	          }
75	        }
76	      }
77	    }
78	
79	    // Unsynced reads and writes
80	    std::vector<AccessEntry> reads;
81	    std::vector<AccessEntry> writes;
82	    // if it is a loop, rotate two times to consider effect of loop.
83	    // simulation based approach to find dependencies
84	    for (size_t i = 0; i < seq.size(); ++i) {
85	      const StmtEntry &s = seq[i];
86	      // check if sync before statement is needed.
87	      bool sync_before_stmt = (syncs_inserted_.count(s.stmt) != 0);
88	      // Apply the syncs added already.
89	
90	      if (sync_before_stmt) {
91	        reads.clear();
92	        writes.clear();
93	      }
94	
95	      for (const AccessEntry &acc : s.access) {
96	        if (acc.type == kRead) {
97	          if (FindConflict(writes, acc, false)) {
98	            sync_before_stmt = true;
99	            break;
100	          }
101	        } else if (acc.type == kWrite) {
102	          if (FindConflict(reads, acc, false) ||
103	              FindConflict(writes, acc, false)) {
104	            sync_before_stmt = true;
105	            break;
106	          }
107	        } else if (acc.type == kSync) {
108	          reads.clear();
109	          writes.clear();
110	        }
111	      }
112	      // If sync is inserted. remove the irrelevant things.
113	      if (sync_before_stmt) {
114	        reads.clear();
115	        writes.clear();
116	      }
117	      // Add the read/write of current statement
118	      for (const AccessEntry &acc : s.access) {
119	        if (acc.type == kRead) {
120	          reads.push_back(acc);
121	        } else if (acc.type == kWrite) {
122	          writes.push_back(acc);
123	        } else if (acc.type == kSync) {
124	          reads.clear();
125	          writes.clear();
126	        }
127	      }
128	
129	      if (sync_before_stmt) {
130	        insert_syncs(s.stmt);
131	      }
132	    }
133	    if (loop != nullptr) {
134	      // Check if the loop body contains any reads in the same sync scope.
135	      // If there are reads, we conservatively keep the sync within the loop
136	      // body to preserve per-iteration ordering when needed. If there are no
137	      // reads (e.g., only writes to shared.dyn), we can safely hoist the sync
138	      // to before the loop to avoid redundant barriers.
139	      bool has_read_in_scope = false;
140	      for (const StmtEntry &s : seq) {
141	        for (const AccessEntry &acc : s.access) {
142	          if (acc.type == kRead && acc.scope == sync_scope_) {
143	            has_read_in_scope = true;
144	            break;
145	          }
146	        }
147	        if (has_read_in_scope)
148	          break;
149	      }
150	      // If there is a loop-carried dependency, insert a single sync
151	      // before the loop rather than hoisting a sync into the loop body.
152	      // This reduces redundant per-iteration synchronizations for cases
153	      // where each iteration touches disjoint regions (e.g., stmatrix
154	      // writes to shared.dyn) and only a global ordering before/after the
155	      // loop is required.
156	      for (size_t i = 0; i < seq.size(); ++i) {
157	        const StmtEntry &s = seq[i];
158	        if (syncs_inserted_.count(s.stmt) != 0)
159	          break;
160	        if (reads.empty() && writes.empty())
161	          break;
162	        bool need_loop_sync = false;
163	        for (const AccessEntry &acc : s.access) {
164	          if (acc.type == kRead) {
165	            if (FindConflict(writes, acc, true)) {
166	              need_loop_sync = true;
167	              break;
168	            }
169	          } else if (acc.type == kWrite) {
170	            if (FindConflict(reads, acc, true) ||
171	                FindConflict(writes, acc, true)) {
172	              need_loop_sync = true;
173	              break;
174	            }
175	          } else if (acc.type == kSync) {
176	            reads.clear();
177	            writes.clear();
178	          }
179	        }
180	        if (need_loop_sync) {
181	          if (!has_read_in_scope) {
182	            // Mark the loop itself to receive a sync before it, instead of
183	            // inserting inside the loop body. This ensures a single sync is
184	            // emitted outside the loop and avoids per-iteration overhead.
185	            insert_syncs(loop);
186	          } else {
187	            // Fall back to inserting before the first conflicting statement
188	            // inside the loop to maintain correctness when reads are present.
189	            insert_syncs(s.stmt);
190	          }
191	          break;
192	        }
193	      }
194	    }
195	    // return the exposed entries, remove unnecessary ones.
196	    int sync_count = 0;
197	    // head are before first sync, tail are after last sync
198	    std::vector<AccessEntry> head, tail;
199	    AccessEntry esync;
200	    esync.threads = this->env_threads();
201	    esync.thread_range = this->ComputeThreadRange(esync.threads);
202	    esync.type = kSync;
203	    esync.scope = sync_scope_;
204	
205	    for (const StmtEntry &s : seq) {
206	      if (syncs_inserted_.count(s.stmt)) {
207	        if (sync_count != 0) {
208	          tail.clear();
209	        } else {
210	          head.push_back(esync);
211	        }
212	        ++sync_count;
213	      }
214	      for (const AccessEntry &acc : s.access) {
215	        if (acc.type == kSync) {
216	          if (sync_count != 0) {
217	            tail.clear();
218	          } else {
219	            head.push_back(esync);
220	          }
221	          ++sync_count;
222	        } else {
223	          if (sync_count != 0) {
224	            tail.push_back(acc);
225	          } else {
226	            head.push_back(acc);
227	          }
228	        }
229	      }
230	    }
231	    head.insert(head.end(), tail.begin(), tail.end());
232	    if (loop != nullptr) {
233	      // clear double buffer flag after a loop is finished.
234	      for (AccessEntry &e : head) {
235	        e.double_buffer_write = false;
236	      }
237	    }
238	    return head;
239	  }
240	
241	private:
242	  // find conflicting entry in vec.
243	  bool FindConflict(const std::vector<AccessEntry> &prev,
244	                    const AccessEntry &curr, bool loop_carry) {
245	    for (const AccessEntry &x : prev) {
246	      if (FindConflict(x, curr, loop_carry)) {
247	        return true;
248	      }
249	    }
250	    return false;
251	  }
252	
253	  bool FindConflict(const AccessEntry &prev, const AccessEntry &curr,
254	                    bool loop_carry) {
255	    // Special case: ignore conflicts between async-copy writes (e.g., TMA
256	    // loads into shared memory). Multiple async writes do not require
257	    // interspersed barriers among themselves. We still respect conflicts with
258	    // reads to ensure visibility before consumption.
259	    if (prev.type == kWrite && curr.type == kWrite && prev.is_async_copy &&
260	        curr.is_async_copy) {
261	      return false;
262	    }
263	    // Access to different buffers does not conflict.
264	    if (!prev.buffer.same_as(curr.buffer)) {
265	      return false;
266	    }
267	
268	    // Assumes no race between threads
269	    // Same index value means no conflicts
270	    // TODO(tqchen) more standard set based testing.
271	    bool has_same_index = true;
272	    bool range_is_equal = true;
273	    bool range_is_overlap = true;
274	
275	    for (const auto &kv : prev.thread_range) {
276	      if (!StructuralEqual()(kv.second, curr.thread_range[kv.first])) {
277	        range_is_equal = false;
278	        break;
279	      }
280	    }
281	
282	    if (prev.buffer_indices.size() != curr.buffer_indices.size()) {
283	      // They are not the same indices, should be conflict.
284	      return true;
285	    }
286	    if (prev.is_pointer_access || curr.is_pointer_access) {
287	      // For accesses created via tvm_access_ptr we may still be able to prove
288	      // disjointness using their byte ranges.  If both sides expose a touched
289	      // interval and we can show they don't overlap, skip the conflict.
290	      if (prev.is_pointer_access && curr.is_pointer_access &&
291	          PointerAccessIsDisjoint(prev, curr)) {
292	        return false;
293	      }
294	      // Otherwise fall back to the conservative answer: treat them as
295	      // overlapping.
296	      return true;
297	    }
298	
299	    for (size_t i = 0; i < prev.buffer_indices.size(); i++) {
300	      auto prev_dtype = prev.dtype;
301	      auto curr_dtype = curr.dtype;
302	
303	      const auto &prev_indice = prev.buffer_indices[i];
304	      const auto &curr_indice = curr.buffer_indices[i];
305	
306	      if (!ExprDeepEqual()(prev_indice, curr_indice)) {
307	        PrimExpr prev_indice_bytes =
308	            analyzer_.Simplify(prev_indice * prev_dtype.bytes());
309	        PrimExpr curr_indice_bytes =
310	            analyzer_.Simplify(curr_indice * curr_dtype.bytes());
311	
312	        has_same_index = false;
313	
314	        // If both are const, we can check if they are disjoint
315	        // by checking if the bounds are disjoint
316	        // [1024, 2048], [2048, 3072] are disjoint
317	        // [1024, 2048], [1024, 1024] are not disjoint
318	        auto prev_bound = analyzer_.const_int_bound(prev_indice_bytes);
319	        auto curr_bound = analyzer_.const_int_bound(curr_indice_bytes);
320	        if (prev_bound.defined() && curr_bound.defined()) {
321	          if ((prev_bound->min_value) > (curr_bound->max_value) ||
322	              (curr_bound->min_value) > (prev_bound->max_value)) {
323	            range_is_overlap = false;
324	            break;
325	          }
326	        }
327	
328	        // if we can prove prev_indice < curr_indice or prev_indice >
329	        // curr_indice, then they are not overlap
330	        auto prev_indices_dtype = prev_indice.dtype();
331	        auto curr_indices_dtype = curr_indice.dtype();
332	        if (prev_indices_dtype.lanes() != curr_indices_dtype.lanes()) {
333	          // can not support different lanes binary op like <, >, <=, >=
334	          // skip otherwise it will lead to error
335	          continue;
336	        }
337	
338	        // provably disjoint means no overlap, for example:
339	        // we can prove that tx - 128 < tx + 128, tx in [0, 128]
340	        // However, we should apply tx split because
341	        // tx < tx + 32 when tx in [0, 128] is not disjoint
342	        // because [0, 128] is not disjoint with [32, 160]
343	        // so we should split tx into tx0 and tx1.
344	
345	        struct ThreadVarInfo {
346	          const char *name_prev;
347	          const char *name_curr;
348	          IterVar iv;
349	        } thread_vars[] = {
350	            {"tx1", "tx2", tx_},
351	            {"ty1", "ty2", ty_},
352	            {"tz1", "tz2", tz_},
353	        };
354	
355	        for (const auto &info : thread_vars) {
356	          Var prev_var(info.name_prev, info.iv->var.dtype());
357	          Var curr_var(info.name_curr, info.iv->var.dtype());
358	          analyzer_.Bind(prev_var, info.iv->dom);
359	          analyzer_.Bind(curr_var, info.iv->dom);
360	          prev_indice_bytes =
361	              Substitute(prev_indice_bytes, {{info.iv->var, prev_var}});
362	          curr_indice_bytes =
363	              Substitute(curr_indice_bytes, {{info.iv->var, curr_var}});
364	        }
365	
366	        bool provably_disjoint =
367	            analyzer_.CanProve(prev_indice_bytes < curr_indice_bytes,
368	                               arith::ProofStrength::kSymbolicBound) ||
369	            analyzer_.CanProve(prev_indice_bytes > curr_indice_bytes,
370	                               arith::ProofStrength::kSymbolicBound);
371	
372	        if (provably_disjoint) {
373	          range_is_overlap = false;
374	          break;
375	        }
376	      }
377	
378	      if (!has_same_index) {
379	        break;
380	      }
381	    }
382	
383	    if (has_same_index && range_is_equal) {
384	      return false;
385	    }
386	
387	    // If this is a read into a double buffer that was previously
388	    // swapped out, then it doesn't conflict.
389	    if (prev.double_buffer_write && curr.type == kRead && !loop_carry) {
390	      return false;
391	    }
392	
393	    // If nothing else allows sharing the same buffer, then they are
394	    // in conflict.
395	    // if range_is_overlap is true, then they are in conflict, we should return
396	    // true. if range_is_overlap is false, then they are not in conflict, we
397	    // should return false.
398	    return range_is_overlap;
399	  }
400	
401	  bool PointerAccessIsDisjoint(const AccessEntry &lhs, const AccessEntry &rhs) {
402	    if (lhs.touched.size() != 1 || rhs.touched.size() != 1) {
403	      return false;
404	    }
405	    PrimExpr lhs_min = analyzer_.Simplify(lhs.touched[0].min());
406	    PrimExpr lhs_max = analyzer_.Simplify(lhs.touched[0].max());
407	    PrimExpr rhs_min = analyzer_.Simplify(rhs.touched[0].min());
408	    PrimExpr rhs_max = analyzer_.Simplify(rhs.touched[0].max());
409	
410	    if (analyzer_.CanProve(lhs_max < rhs_min,
411	                           arith::ProofStrength::kSymbolicBound)) {
412	      return true;
413	    }
414	    if (analyzer_.CanProve(rhs_max < lhs_min,
415	                           arith::ProofStrength::kSymbolicBound)) {
416	      return true;
417	    }
418	    return false;
419	  }
420	
421	  void VisitStmt_(const AttrStmtNode *op) final {
422	    if (op->attr_key == tvm::tir::attr::thread_extent) {
423	      IterVar iv = Downcast<IterVar>(op->node);
424	      if (iv->thread_tag == "threadIdx.x") {
425	        tx_ = iv;
426	      } else if (iv->thread_tag == "threadIdx.y") {
427	        ty_ = iv;
428	      } else if (iv->thread_tag == "threadIdx.z") {
429	        tz_ = iv;
430	      }
431	    }
432	    TileLangStorageAccessVisitor::VisitStmt_(op);
433	  }
434	
435	  void insert_syncs(const Object *obj) {
436	    if (syncs_inserted_.count(obj))
437	      return;
438	    syncs_inserted_.insert(obj);
439	  }
440	
441	private:
442	  // Member variables
443	  IterVar tx_ =
444	      IterVar(Range::FromMinExtent(0, 1), Var("tx"), IterVarType::kDataPar);
445	  IterVar ty_ =
446	      IterVar(Range::FromMinExtent(0, 1), Var("ty"), IterVarType::kDataPar);
447	  IterVar tz_ =
448	      IterVar(Range::FromMinExtent(0, 1), Var("tz"), IterVarType::kDataPar);
449	  // synchronization scope
450	  StorageScope sync_scope_;
451	};
452	
453	// There are cases where necessary syncthreads is not inserted by
454	// ThreadSyncInserter. For example, syncthreads is needed after async_wait_queue
455	// in the second loop below, but since ThreadSyncInserter is not aware of the
456	// asynchronous semantics, it cannot tell that the syncthreads is needed there.
457	//
458	// // Pipeline prologue
459	// for i in range(125):
460	//    async_commit_queue(0):
461	//       async_scope:
462	//          shared[(i + 3) % 4] = ...
463	// ...
464	//
465	// // Pipeline Epilogue
466	// for i in range(3):
467	//    async_wait_queue(0, 2 - i):
468	//       local[...] = shared[(i + 125) % 4]
469	
470	// This class adds syncthreads after all async_wait_queue. That includes
471	// syncthreads that can be inserted by ThreadSyncInserter as well, but
472	// ThreadSyncInserter will not insert duplicate syncthreads if it finds an
473	// existing one at the synchronization point.
474	class ThreadSyncAfterWaitQueueInserter : public StmtExprMutator {
475	public:
476	  explicit ThreadSyncAfterWaitQueueInserter(StorageScope sync_scope)
477	      : sync_scope_(std::move(sync_scope)) {}
478	
479	  Stmt VisitStmt_(const AttrStmtNode *op) final {
480	    if (op->attr_key == tvm::tir::attr::async_wait_queue_scope) {
481	      auto sync = Evaluate(Call(DataType::Int(32), builtin::tvm_storage_sync(),
482	                                {StringImm(sync_scope_.to_string())}));
483	      auto inner = op->body.as<AttrStmtNode>();
484	      ICHECK(inner &&
485	             inner->attr_key == tvm::tir::attr::async_wait_inflight_count);
486	      auto zero = make_zero(DataType::Int(32));
487	      auto new_body = SeqStmt({sync, inner->body});
488	      return AttrStmt(zero, tvm::tir::attr::async_wait_queue_scope, op->value,
489	                      AttrStmt(zero, tvm::tir::attr::async_wait_inflight_count,
490	                               inner->value, new_body));
491	    }
492	    return StmtExprMutator::VisitStmt_(op);
493	  }
494	
495	private:
496	  StorageScope sync_scope_;
497	};
498	
499	class ThreadSyncInserter : public StmtExprMutator {
500	public:
501	  ThreadSyncInserter(StorageScope sync_scope,
502	                     const std::unordered_set<const Object *> &syncs)
503	      : sync_scope_(std::move(sync_scope)), syncs_(syncs) {}
504	
505	  Stmt VisitStmt(const Stmt &stmt) final {
506	    if (syncs_.empty())
507	      return stmt;
508	    if (syncs_.count(stmt.get())) {
509	      Stmt barrier;
510	      if (sync_scope_.rank == StorageRank::kGlobal) {
511	        barrier = MakeGlobalBarrier();
512	      } else {
513	        barrier = Evaluate(Call(DataType::Int(32), builtin::tvm_storage_sync(),
514	                                {StringImm(sync_scope_.to_string())}));
515	      }
516	      // Mutate after query, to avoid stmt change.
517	      auto ret = StmtExprMutator::VisitStmt(stmt);
518	      ret = SeqStmt({barrier, ret});
519	      return ret;
520	    } else {
521	      return StmtExprMutator::VisitStmt(stmt);
522	    }
523	  }
524	  PrimExpr VisitExpr_(const BufferLoadNode *op) final {
525	    if (sync_scope_.rank == StorageRank::kGlobal &&
526	        GetScope(op->buffer->data).rank == StorageRank::kGlobal) {
527	      ++rw_stats_[op->buffer->data].read_count;
528	    }
529	    return StmtExprMutator::VisitExpr_(op);
530	  }
531	  Stmt VisitStmt_(const BufferStoreNode *op) final {
532	    if (sync_scope_.rank == StorageRank::kGlobal &&
533	        GetScope(op->buffer->data).rank == StorageRank::kGlobal) {
534	      ++rw_stats_[op->buffer->data].write_count;
535	    }
536	    return StmtExprMutator::VisitStmt_(op);
537	  }
538	  Stmt VisitStmt_(const AttrStmtNode *op) final {
539	    if (op->attr_key == tvm::tir::attr::thread_extent) {
540	      bool temp = true;
541	      std::swap(temp, in_thread_env_);
542	      thread_extents_.push_back(op);
543	      Stmt ret = StmtExprMutator::VisitStmt_(op);
544	      thread_extents_.pop_back();
545	      std::swap(temp, in_thread_env_);
546	      // first thread scope.
547	      if (!in_thread_env_ && sync_scope_.rank == StorageRank::kGlobal) {
548	        ret = InitGlobalBarrier(ret.as<AttrStmtNode>());
549	        num_blocks_ = PrimExpr();
550	        is_lead_ = PrimExpr();
551	      }
552	      return ret;
553	    } else {
554	      return StmtExprMutator::VisitStmt_(op);
555	    }
556	  }
557	
558	  PrimExpr VisitExpr_(const CallNode *op) final {
559	    if (op->op.same_as(builtin::tvm_access_ptr())) {
560	      PrimExpr expr = StmtExprMutator::VisitExpr_(op);
561	      op = expr.as<CallNode>();
562	      ICHECK_EQ(op->args.size(), 5U);
563	      Var buffer_var(Downcast<Var>(op->args[1]));
564	      const IntImmNode *flag = op->args[4].as<IntImmNode>();
565	      if ((flag->value & 1) && sync_scope_.rank == StorageRank::kGlobal &&
566	          GetScope(buffer_var).rank == StorageRank::kGlobal) {
567	        ++rw_stats_[buffer_var].read_count;
568	      }
569	      if (flag->value & 2 && sync_scope_.rank == StorageRank::kGlobal &&
570	          GetScope(buffer_var).rank == StorageRank::kGlobal) {
571	        ++rw_stats_[buffer_var].write_count;
572	      }
573	      return expr;
574	    } else if (op->op.same_as(builtin::address_of())) {
575	      PrimExpr expr = StmtExprMutator::VisitExpr_(op);
576	      op = expr.as<CallNode>();
577	      ICHECK_EQ(op->args.size(), 1U)
578	          << "address_of should only have one argument (Buffer)";
579	
580	      if (auto load = op->args[0].as<BufferLoadNode>()) {
581	        Var buffer_var(Downcast<Var>(load->buffer->data));
582	        if (sync_scope_.rank == StorageRank::kGlobal &&
583	            GetScope(buffer_var).rank == StorageRank::kGlobal) {
584	          ++rw_stats_[buffer_var].read_count;
585	        }
586	        if (sync_scope_.rank == StorageRank::kGlobal &&
587	            GetScope(buffer_var).rank == StorageRank::kGlobal) {
588	          ++rw_stats_[buffer_var].write_count;
589	        }
590	        return expr;
591	      } else {
592	        return StmtExprMutator::VisitExpr_(op);
593	      }
594	    } else {
595	      return StmtExprMutator::VisitExpr_(op);
596	    }
597	  }
598	
599	private:
600	  // RW statistics about data
601	  struct Entry {
602	    int read_count{0};
603	    int write_count{0};
604	  };
605	
606	  // Get current storage scope.
607	  StorageScope GetScope(Var buffer_var) const {
608	    return StorageScope::Create(GetPtrStorageScope(std::move(buffer_var)));
609	  }
610	
611	  // private functions.
612	  Stmt InitGlobalBarrier(const AttrStmtNode *op) {
613	    ICHECK(op != nullptr);
614	    Array<PrimExpr> pargs = {
615	        StringImm(runtime::symbol::tvm_prepare_global_barrier)};
616	    Stmt prep =
617	        Evaluate(Call(DataType::Int(32), builtin::tvm_call_packed(), pargs));
618	    Stmt body = op->body;
619	    for (const auto &kv : rw_stats_) {
620	      const auto &e = kv.second;
621	      if (e.read_count != 0 && e.write_count != 0) {
622	        body = AttrStmt(kv.first, tvm::tir::attr::volatile_scope, 1, body);
623	      }
624	    }
625	    rw_stats_.clear();
626	    Stmt kinit = Evaluate(
627	        Call(DataType::Int(32), builtin::tvm_global_barrier_kinit(), {}));
628	    body = SeqStmt({kinit, body});
629	    body = AttrStmt(op->node, op->attr_key, op->value, body);
630	    return SeqStmt({prep, body});
631	  }
632	  Stmt MakeGlobalBarrier() {
633	    ICHECK(sync_scope_.rank == StorageRank::kGlobal);
634	    if (!num_blocks_.defined()) {
635	      ICHECK(!is_lead_.defined());
636	      num_work_dim_ = thread_extents_.size();
637	      for (const AttrStmtNode *attr : thread_extents_) {
638	        IterVar iv = Downcast<IterVar>(attr->node);
639	        runtime::ThreadScope s = runtime::ThreadScope::Create(iv->thread_tag);
640	        if (s.rank == 0) {
641	          num_blocks_ =
642	              (num_blocks_.defined() ? attr->value * num_blocks_ : attr->value);
643	        } else if (s.rank == 1) {
644	          PrimExpr cond = iv->var == make_zero(iv->var.dtype());
645	          is_lead_ = is_lead_.defined() ? (is_lead_ && cond) : cond;
646	        }
647	      }
648	    } else {
649	      ICHECK_EQ(num_work_dim_, thread_extents_.size());
650	    }
651	    return Evaluate(
652	        Call(DataType::Int(32), builtin::tvm_storage_sync(),
653	             {StringImm(sync_scope_.to_string()), is_lead_, num_blocks_}));
654	  }
655	  // data structure.
656	  StorageScope sync_scope_;
657	  const std::unordered_set<const Object *> &syncs_;
658	
659	  // The read write statistics of storage
660	  std::unordered_map<Var, Entry, ObjectPtrHash, ObjectPtrEqual> rw_stats_;
661	  // The statistics for global barrier
662	  bool in_thread_env_{false};
663	  // memorized results
664	  std::vector<const AttrStmtNode *> thread_extents_;
665	  size_t num_work_dim_{0};
666	  PrimExpr num_blocks_;
667	  PrimExpr is_lead_;
668	};
