670	class ThreadPartialSyncRewriter : public IRMutatorWithAnalyzer {
671	public:
672	  static Stmt Rewrite(Stmt stmt) {
673	    arith::Analyzer analyzer;
674	    ThreadPartialSyncRewriter rewriter(&analyzer);
675	    return rewriter(std::move(stmt));
676	  }
677	
678	private:
679	  explicit ThreadPartialSyncRewriter(arith::Analyzer *analyzer)
680	      : IRMutatorWithAnalyzer(analyzer) {}
681	
682	  Stmt VisitStmt_(const EvaluateNode *op) final {
683	    const CallNode *call = nullptr;
684	    if (op->value->IsInstance<CallNode>()) {
685	      call = op->value.as<CallNode>();
686	      if (call->op.same_as(builtin::tvm_storage_sync())) {
687	        const auto &args = call->args;
688	        ICHECK(!args.empty());
689	        const auto *scope_node = args[0].as<StringImmNode>();
690	        ICHECK(scope_node != nullptr);
691	        const std::string &scope = scope_node->value;
692	
693	        if (args.size() != 1 || (scope != "shared" && scope != "shared.dyn")) {
694	          return IRMutatorWithAnalyzer::VisitStmt_(op);
695	        }
696	
697	        return ProcessSharedSync(call, scope);
698	      }
699	    }
700	    return IRMutatorWithAnalyzer::VisitStmt_(op);
701	  }
702	
703	  Stmt ProcessSharedSync(const CallNode *op, const std::string &scope) {
704	    // Get thread bounds
705	    auto bound_tx = analyzer_->const_int_bound(tx_);
706	    auto bound_ty = analyzer_->const_int_bound(ty_);
707	    auto bound_tz = analyzer_->const_int_bound(tz_);
708	
709	    // Check if all threads are participating (full extent)
710	    if (IsFullThreadExtent(tx_, bound_tx) &&
711	        IsFullThreadExtent(ty_, bound_ty) &&
712	        IsFullThreadExtent(tz_, bound_tz)) {
713	      return Evaluate(IRMutatorWithAnalyzer::VisitExpr_(op));
714	    }
715	
716	    // Calculate thread extents
717	    auto extent_tx = CalculateThreadExtent(tx_, bound_tx);
718	    auto extent_ty = CalculateThreadExtent(ty_, bound_ty);
719	    auto extent_tz = CalculateThreadExtent(tz_, bound_tz);
720	
721	    // Create or get barrier info
722	    ThreadBoundKey key{bound_tx->min_value, bound_tx->max_value,
723	                       bound_ty->min_value, bound_ty->max_value,
724	                       bound_tz->min_value, bound_tz->max_value};
725	
726	    auto [barrier_id, thread_count] =
727	        GetOrCreateBarrier(key, extent_tx, extent_ty, extent_tz);
728	    if (thread_count % 32 != 0) {
729	      // TODO(lei): This is a workaround for the case where the thread count is
730	      // not a multiple of 32. we should enhance the pass to analysis index
731	      // instead of buffer expression etc.
732	      return Stmt();
733	    }
734	
735	    // Create new sync call with barrier info
736	    Array<PrimExpr> new_args = {StringImm(scope),
737	                                IntImm(DataType::Int(32), barrier_id),
738	                                IntImm(DataType::Int(32), thread_count)};
739	    return Evaluate(Call(op->dtype, op->op, new_args));
740	  }
741	
742	  std::pair<size_t, size_t> GetOrCreateBarrier(const ThreadBoundKey &key,
743	                                               size_t extent_tx,
744	                                               size_t extent_ty,
745	                                               size_t extent_tz) {
746	    if (barrier_id_map_.count(key)) {
747	      return {barrier_id_map_[key], thread_count_map_[key]};
748	    }
749	
750	    size_t barrier_id =
751	        barrier_id_map_.size() +
752	        static_cast<size_t>(ReservedNamedBarriers::kFirstUsedBarrier);
753	    size_t thread_count = extent_tx * extent_ty * extent_tz;
754	
755	    barrier_id_map_[key] = barrier_id;
756	    thread_count_map_[key] = thread_count;
757	
758	    return {barrier_id, thread_count};
759	  }
760	
761	  size_t CalculateThreadExtent(const IterVar &iv,
762	                               const arith::ConstIntBound &bound) {
763	    if (!analyzer_->const_int_bound.IsBound(iv->var)) {
764	      return 1;
765	    }
766	    return bound->max_value - bound->min_value + 1;
767	  }
768	
769	  Stmt VisitStmt_(const AttrStmtNode *op) final {
770	    if (op->attr_key == tvm::tir::attr::thread_extent) {
771	      IterVar iv = Downcast<IterVar>(op->node);
772	      if (iv->thread_tag == "threadIdx.x") {
773	        tx_ = iv;
774	      } else if (iv->thread_tag == "threadIdx.y") {
775	        ty_ = iv;
776	      } else if (iv->thread_tag == "threadIdx.z") {
777	        tz_ = iv;
778	      }
779	    }
780	    return IRMutatorWithAnalyzer::VisitStmt_(op);
781	  }
782	
783	  bool IsFullThreadExtent(const IterVar &iv,
784	                          const arith::ConstIntBound &bound) {
785	    if (!analyzer_->const_int_bound.IsBound(iv->var)) {
786	      return true;
787	    }
788	
789	    if (!iv->dom.defined()) {
790	      return true;
791	    }
792	
793	    const auto *min_node = iv->dom->min.as<IntImmNode>();
794	    const auto *extent_node = iv->dom->extent.as<IntImmNode>();
795	
796	    int64_t min = min_node->value;
797	    int64_t extent = extent_node->value;
798	    int64_t max = min + extent - 1;
799	
800	    return min == bound->min_value && max == bound->max_value;
801	  }
802	
803	  // Member variables
804	  IterVar tx_ =
805	      IterVar(Range::FromMinExtent(0, 1), Var("tx"), IterVarType::kDataPar);
806	  IterVar ty_ =
807	      IterVar(Range::FromMinExtent(0, 1), Var("ty"), IterVarType::kDataPar);
808	  IterVar tz_ =
809	      IterVar(Range::FromMinExtent(0, 1), Var("tz"), IterVarType::kDataPar);
810	  std::unordered_map<ThreadBoundKey, size_t> barrier_id_map_;
811	  std::unordered_map<ThreadBoundKey, size_t> thread_count_map_;
812	};
813	
814	PrimFunc TileLangThreadSync(PrimFunc func, const std::string &storage_scope) {
815	  StorageScope sync_scope = StorageScope::Create(storage_scope);
816	  auto *n = func.CopyOnWrite();
817	  auto stmt = n->body;
818	  if (sync_scope.rank == StorageRank::kShared && sync_scope.tag.empty()) {
819	    stmt = ThreadSyncAfterWaitQueueInserter(sync_scope)(stmt);
820	  }
821	  TileLangThreadSyncPlanner planner(sync_scope);
822	  for (const auto &[_, buffer] : func->buffer_map) {
823	    planner.SetBufferDataToBuffer(buffer->data, buffer);
824	  }
825	  planner(stmt);
826	
827	  stmt =
828	      ThreadSyncInserter(sync_scope, planner.syncs_inserted_)(std::move(stmt));
829	  n->body = ThreadPartialSyncRewriter::Rewrite(std::move(stmt));
830	  return func;
831	}
832	
833	using namespace tir::transform;
834	
835	namespace transform {
836	
837	tvm::transform::Pass ThreadSync(const String &storage_scope) {
838	  auto pass_func = [storage_scope](PrimFunc f, const IRModule &m,
839	                                   const PassContext &ctx) {
840	    auto *n = f.CopyOnWrite();
841	    // Check if thread storage sync is disabled
842	    bool disable_syncthreads =
843	        ctx->GetConfig(kDisableThreadStorageSync, Bool(false)).value()->value;
844	    if (disable_syncthreads) {
845	      return f;
846	    }
847	    return tl::TileLangThreadSync(std::move(f), storage_scope);
848	    ;
849	  };
850	  return CreatePrimFuncPass(pass_func, 0, "tl.ThreadSync", {});
851	}
852	
853	TVM_FFI_STATIC_INIT_BLOCK() {
854	  namespace refl = tvm::ffi::reflection;
855	  refl::GlobalDef().def("tl.transform.ThreadSync", ThreadSync);
856	}
857	
858	} // namespace transform
859	} // namespace tl
860	} // namespace tvm
