469	  using AllocEntry = LinearAccessPatternFinder::AllocEntry;
470	
471	  Stmt Rewrite(Stmt stmt, bool detect_inplace, bool enable_reuse,
472	               bool reuse_require_exact_matched_dtype,
473	               Map<Var, PrimExpr> local_var_init_map = {}) {
474	    detect_inplace_ = detect_inplace;
