605	    if (attach_map_.count(op)) {
606	      auto &svec = attach_map_[op];
607	      Stmt stmt = StmtExprMutator::VisitStmt_(op);
608	      op = stmt.as<ForNode>();
609	      return For(op->loop_var, op->min, op->extent, op->kind,
610	                 MakeAttach(svec, op->body), op->thread_binding,
611	                 op->annotations);
