621	  Stmt VisitStmt_(const DeclBufferNode *op) final {
622	    if (hoisted_buffer_decls_.count(op->buffer.get()) ||
623	        !all_buffers_accessed_.count(op->buffer.get())) {
624	      return this->VisitStmt(op->body);
625	    }
