627	
628	    if (auto it = alloc_map_.find(op->buffer->data.get());
629	        it != alloc_map_.end()) {
630	      Buffer buf = RemapBuffer(op->buffer, it->second->alloc_var);
631	      node.CopyOnWrite()->buffer = buf;
