636	private:
637	  struct StorageEntry {
638	    // The scope that this alloc attaches after
639	    // For shared/local memory it is beginning of the thread extent.
640	    // for global memory it is nullptr, means beginning of everything.
641	    const Object *attach_scope_{nullptr};
642	    // The constant size of the buffer in bits, only used if it is constant
643	    uint64_t const_nbits{0};
644	    // The storage scope.
645	    StorageScope scope;
646	    // The physical dimensionality of the allocations.  Since
647	    // StorageRewrite is applied after StorageFlatten/FlattenBuffer,
648	    // this is size of `AllocateNode::extents`.  If moved
649	    size_t ndim{};
650	    // Allocs that shares this entry.
651	    std::vector<const AllocateNode *> allocs;
652	    // The children of this entry, not including itself.
653	    std::vector<StorageEntry *> merged_children;
654	    // The replacement Allocate, if any.  May also include associated
655	    // DeclBuffer statement.
656	    std::vector<Stmt> alloc_nest;
657	    // The var expr of new allocation.
658	    Var alloc_var;
659	    // The allocation element type.
660	    DataType elem_type;
661	    // This is non-zero if this allocate is folded into another one
662	    // the address(in bits) becomes alloc_var + bits_offset;
663	    // can be effectively converted to the element type.
664	    // We need to convert bit_offset to offset of specific element type later.
665	    //
666	    // We use bits(instead of bytes) to support non-conventional indexing in
667	    // hardware. When we are merging buffer together, the bits_offset are set to
668	    // be aligned to certain value given by the max_simd_bits property of the
669	    // special memory.
670	    //
671	    // This allows effective sharing among different types as long as their
672	    // alignment requirement fits into the max_simd_bits.
673	    uint64_t bits_offset{0};
674	  };
